* {
  box-sizing: border-box;
}

:root {
  --game-shell-width: min(1200px, 96vw);
  --game-shell-height: min(700px, 92vh);
  --game-shell-height: min(700px, 92dvh);
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: Arial, sans-serif;
  background: radial-gradient(circle at top, #13284a, #02050b 65%);
  color: white;
  overflow: hidden;
}

.stars {
  position: fixed;
  inset: 0;
  background-image:
    radial-gradient(white 1px, transparent 1px),
    radial-gradient(rgba(255,255,255,0.45) 1px, transparent 1px);
  background-size: 80px 80px, 140px 140px;
  background-position: 0 0, 40px 60px;
  opacity: 0.45;
}

.screen {
  position: relative;
  z-index: 2;
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px;
}

.card {
  display: none;
  width: 100%;
  max-width: 430px;
  background: rgba(8, 15, 30, 0.9);
  border: 1px solid #263a63;
  border-radius: 18px;
  padding: 34px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.55);
  text-align: center;
}

.card.active {
  display: block;
}

h1 {
  font-size: 56px;
  letter-spacing: 8px;
  margin: 0 0 18px;
}

h2 {
  margin-top: 0;
}

.subtitle {
  color: #b9c8e8;
  margin-bottom: 28px;
}

.menu {
  display: grid;
  gap: 14px;
}

button {
  width: 100%;
  border: none;
  border-radius: 10px;
  padding: 13px 16px;
  background: #1f5fb7;
  color: white;
  font-size: 15px;
  font-weight: 800;
  cursor: pointer;
}

button:hover {
  background: #2a6ed0;
}

button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

button.secondary,
.secondary-hud-btn {
  background: transparent;
  border: 1px solid #3b507a;
  color: #c7d3ea;
}

.back-gap {
  margin-top: 14px;
}

input {
  width: 100%;
  margin-bottom: 12px;
  padding: 13px;
  border-radius: 10px;
  border: 1px solid #34486f;
  background: #07111f;
  color: white;
  font-size: 15px;
}

input::placeholder {
  color: #7f8da8;
}

.message {
  min-height: 20px;
  margin-bottom: 0;
  color: #ffb86b;
}

/* Shared full screens */

.hub-screen,
.market-screen,
.hangar-screen,
.space-screen {
  display: none;
  width: var(--game-shell-width);
  max-width: 1200px;
  height: var(--game-shell-height);
  max-height: 700px;
  border-radius: 18px;
  overflow: hidden;
  position: relative;
  box-shadow: 0 24px 80px rgba(0,0,0,0.75);
  border: 1px solid #2c4f75;
}

.hub-screen.active,
.market-screen.active,
.hangar-screen.active,
.space-screen.active {
  display: block;
}

.hub-screen {
  background:
    linear-gradient(to top, rgba(2,5,11,0.78), rgba(2,5,11,0.08)),
    url("asteron-prime-space-station-hub.png");
  background-size: cover;
  background-position: center;
}

.hub-overlay {
  position: absolute;
  inset: 0;
  padding: 34px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.hub-header {
  text-align: center;
  text-shadow: 0 0 14px rgba(0,0,0,0.9);
}

.hub-header p {
  margin: 0 0 6px;
  color: #7fdfff;
  letter-spacing: 3px;
  font-weight: 900;
}

.hub-header h2 {
  margin: 0;
  font-size: 48px;
  letter-spacing: 4px;
}

.hub-actions {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
  margin-top: auto;
}

.hub-actions button {
  min-height: 82px;
  font-size: 22px;
  letter-spacing: 1px;
  background: rgba(8, 18, 34, 0.86);
  border: 1px solid #3c8fc7;
  box-shadow: 0 0 22px rgba(0, 180, 255, 0.18);
}

.hub-actions button:hover {
  background: rgba(21, 77, 155, 0.9);
  transform: translateY(-2px);
}

.logout-btn {
  position: absolute;
  right: 24px;
  top: 24px;
  width: auto;
  padding: 9px 14px;
  background: rgba(0,0,0,0.45);
  border: 1px solid #526a92;
  color: #d9e6ff;
}

.save-status-indicator {
  position: fixed;
  right: 18px;
  bottom: 16px;
  z-index: 220;
  max-width: min(280px, calc(100vw - 36px));
  padding: 6px 10px;
  border: 1px solid rgba(127, 223, 255, 0.24);
  border-radius: 999px;
  background: rgba(1, 8, 18, 0.72);
  color: rgba(203, 225, 242, 0.78);
  font-size: 0.66rem;
  font-weight: 800;
  letter-spacing: 0.03em;
  pointer-events: none;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.24);
}

.save-status-indicator[data-state="saving"] {
  border-color: rgba(255, 220, 95, 0.38);
  color: rgba(255, 232, 163, 0.88);
}

.save-status-indicator[data-state="cloud"] {
  border-color: rgba(52, 229, 154, 0.34);
  color: rgba(159, 255, 205, 0.88);
}

.save-status-indicator[data-state="cloud-failed"] {
  border-color: rgba(255, 118, 132, 0.46);
  color: rgba(255, 198, 207, 0.92);
}

/* Marketplace */

.market-screen {
  background:
    linear-gradient(to bottom, rgba(2,5,11,0.88), rgba(2,5,11,0.96)),
    url("asteron-prime-space-station-hub.png");
  background-size: cover;
  background-position: center;
  padding: 28px;
}

.market-header,
.hangar-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 20px;
}

.market-header p,
.hangar-header p {
  margin: 0 0 6px;
  color: #7fdfff;
  letter-spacing: 3px;
  font-weight: 900;
}

.market-header h2,
.hangar-header h2 {
  margin: 0;
  font-size: 38px;
  letter-spacing: 3px;
}

.screen-back-btn {
  width: auto;
  padding: 10px 18px;
  background: rgba(8, 18, 34, 0.9);
  border: 1px solid #3c8fc7;
}

.market-summary {
  display: flex;
  gap: 18px;
  flex-wrap: wrap;
  background: rgba(0,0,0,0.55);
  border: 1px solid #3c8fc7;
  border-radius: 12px;
  padding: 14px;
  margin-bottom: 18px;
  color: #d9e6ff;
}

.market-goods {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
}

.market-item {
  background: rgba(0,0,0,0.62);
  border: 1px solid rgba(60,143,199,0.9);
  border-radius: 12px;
  padding: 16px;
}

.market-item h3 {
  margin: 0 0 8px;
}

.market-item p {
  margin: 6px 0;
  color: #c7d3ea;
}

.market-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  align-items: center;
}

.market-actions button {
  min-height: 42px;
}

.qty-input {
  width: 80px;
  margin: 0;
  padding: 10px;
  text-align: center;
}

/* Hangar */

.hangar-screen {
  background:
    linear-gradient(to bottom, rgba(2,5,11,0.88), rgba(2,5,11,0.96)),
    url("asteron-prime-space-station-hub.png");
  background-size: cover;
  background-position: center;
  padding: 28px;
}

.hangar-layout {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 18px;
  height: calc(100% - 90px);
}

.hangar-ship-panel,
.attachment-panel {
  background: rgba(0,0,0,0.62);
  border: 1px solid rgba(60,143,199,0.9);
  border-radius: 14px;
  padding: 18px;
  min-height: 0;
}

.hangar-ship-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.hangar-ship-img {
  width: 100%;
  max-width: 290px;
  max-height: 280px;
  object-fit: contain;
  display: block;
  margin-bottom: 18px;
}

.ship-stats {
  width: 100%;
  display: grid;
  gap: 8px;
  color: #d9e6ff;
}

.attachment-panel {
  overflow-y: auto;
  padding-right: 12px;
}

.attachment-panel h3 {
  margin: 0 0 12px;
}

.installed-attachments,
.available-attachments,
.ship-shop {
  display: grid;
  gap: 8px;
  margin-bottom: 20px;
}

.attachment-card,
.ship-card {
  display: grid;
  grid-template-columns: 70px 1fr auto;
  gap: 10px;
  align-items: center;
  background: rgba(8, 18, 34, 0.82);
  border: 1px solid #3c8fc7;
  border-radius: 12px;
  padding: 10px;
}

.ship-card {
  grid-template-columns: 95px 1fr auto;
}

.attachment-card img {
  width: 70px;
  height: 54px;
  object-fit: contain;
  background: rgba(0,0,0,0.4);
}

.ship-card img {
  width: 95px;
  height: 70px;
  object-fit: contain;
}

.attachment-card h4,
.ship-card h4 {
  margin: 0 0 4px;
}

.attachment-card p,
.ship-card p {
  margin: 2px 0;
  color: #b9c8e8;
  font-size: 13px;
}

.attachment-card button,
.ship-card button {
  width: auto;
  min-width: 86px;
  padding: 9px 12px;
}

.empty-slot {
  color: #7f8da8;
  border: 1px dashed #3c8fc7;
  border-radius: 12px;
  padding: 14px;
}

/* Space */

.space-screen {
  background:
    linear-gradient(to top, rgba(2,5,11,0.2), rgba(2,5,11,0.02)),
    url("space-screen-background.png");
  background-size: cover;
  background-position: center;
}

.space-screen.empty-node {
  background:
    linear-gradient(to top, rgba(2,5,11,0.2), rgba(2,5,11,0.02)),
    url("space-empty.png");
  background-size: cover;
  background-position: center;
}

.clickable-planet,
.clickable-planet:hover,
.clickable-planet:focus,
.clickable-planet:active {
  position: absolute;
  top: 42px;
  right: 62px;
  width: 145px;
  height: 145px;
  border-radius: 50%;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  cursor: pointer;
  z-index: 9;
  pointer-events: auto;
}

.node-name-tag {
  position: absolute;
  top: 18px;
  left: 24px;
  z-index: 4;
  color: rgba(220, 244, 255, 0.45);
  font-weight: 900;
  letter-spacing: 1px;
}

.asteroid-target {
  position: absolute;
  top: 150px;
  right: 230px;
  width: 118px;
  height: 118px;
  display: none;
  align-items: center;
  justify-content: center;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0;
  z-index: 6;
}

.asteroid-target.visible {
  display: flex;
}

.asteroid-target img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  pointer-events: none;
  filter: drop-shadow(0 0 12px rgba(120, 220, 255, 0.35));
}

.asteroid-target.selected img {
  filter: drop-shadow(0 0 16px rgba(255, 210, 90, 0.9));
}

/* Sector map */

.sector-map {
  display: none;
  position: absolute;
  inset: 0;
  z-index: 10;
  background:
    linear-gradient(180deg, rgba(2, 7, 16, 0.78), rgba(2, 6, 14, 0.9)),
    radial-gradient(circle at 50% 50%, rgba(21, 77, 155, 0.10), transparent 36%),
    radial-gradient(circle at 18% 24%, rgba(80, 140, 220, 0.08), transparent 24%),
    radial-gradient(circle at 84% 72%, rgba(80, 140, 220, 0.08), transparent 24%),
    url("cosmic_nebula_in_deep_space.png");
  background-size: cover;
  background-position: center;
  border: 1px solid #3c8fc7;
  border-radius: 18px;
  box-shadow: 0 0 40px rgba(0,0,0,0.8);
  overflow: hidden;
}

.sector-map.active {
  display: block;
}

.map-title {
  position: absolute;
  top: 24px;
  left: 28px;
  z-index: 4;
  color: #7fdfff;
  font-weight: 900;
  letter-spacing: 3px;
  font-size: 18px;
}

.close-map-btn {
  position: absolute;
  right: 24px;
  top: 22px;
  z-index: 5;
  width: 46px;
  height: 46px;
  padding: 0;
  border-radius: 10px;
  background: rgba(8, 18, 34, 0.9);
  border: 1px solid #3c8fc7;
  color: #dff4ff;
  font-size: 28px;
  line-height: 1;
}

.sector-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.svg-route {
  stroke: rgba(165, 210, 230, 0.42);
  stroke-width: 0.18;
  stroke-linecap: round;
}

.svg-route.available {
  stroke: rgba(127, 223, 255, 0.95);
  stroke-width: 0.28;
  filter: drop-shadow(0 0 2px rgba(127, 223, 255, 0.8));
}

.svg-node-hit {
  fill: transparent;
  cursor: pointer;
}

.svg-space-node {
  fill: #f2fbff;
  filter: drop-shadow(0 0 2px rgba(210, 245, 255, 0.95));
}

.svg-space-node.locked {
  opacity: 0.35;
}

.svg-planet-ring {
  fill: none;
  stroke: rgba(150, 225, 255, 0.72);
  stroke-width: 0.25;
}

.svg-current-ring {
  fill: none;
  stroke: #00d084;
  stroke-width: 0.45;
  filter: drop-shadow(0 0 3px rgba(0, 208, 132, 0.95));
}

.svg-planet-label {
  fill: #e3edf8;
  font-size: 2.1px;
  text-anchor: middle;
  dominant-baseline: middle;
  paint-order: stroke;
  stroke: rgba(0, 0, 0, 0.85);
  stroke-width: 0.45px;
  stroke-linejoin: round;
}

/* Space HUD */

.space-combat-hud {
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 22px;
  min-height: 170px;
  display: flex;
  gap: 10px;
  z-index: 5;
  pointer-events: auto;
}

.vertical-stats {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  background: rgba(0, 0, 0, 0.72);
  border: 1px solid #3c8fc7;
  border-radius: 12px;
  padding: 9px;
  box-shadow: 0 0 18px rgba(0, 140, 255, 0.14);
  flex: 0 0 auto;
}

.stat-col {
  width: 45px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}

.stat-value {
  color: #dff4ff;
  font-size: 11px;
  font-weight: 900;
  min-height: 13px;
  text-align: center;
}

.stat-meter {
  position: relative;
  width: 21px;
  height: 82px;
  border: 1px solid #4a5e7b;
  background: #08101b;
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  align-items: flex-end;
  box-shadow: inset 0 0 10px rgba(0,0,0,0.65);
}

.stat-fill {
  width: 100%;
  height: 0%;
  transition: height 0.25s ease;
}

.jump-fill {
  background: linear-gradient(180deg, #ff6e7e, #d91c2d);
}

.hull-fill {
  background: linear-gradient(180deg, #f2e676, #ccb72c);
}

.shield-fill {
  background: linear-gradient(180deg, #67c9ff, #1e60d7);
}

.stat-btn {
  width: 45px;
  min-height: 36px;
  padding: 4px 2px;
  font-size: 8.5px;
  font-weight: 900;
  line-height: 1.05;
  text-align: center;
  border: 1px solid #2f8fcb;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(8, 28, 55, 0.96), rgba(5, 14, 28, 0.96));
  color: #ffffff;
  cursor: pointer;
}

.static-btn {
  cursor: default;
}

#jumpBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.ship-display-panel,
.hud-panel {
  background: rgba(0, 0, 0, 0.72);
  border: 1px solid #3c8fc7;
  border-radius: 12px;
  padding: 12px;
  box-shadow: 0 0 18px rgba(0, 140, 255, 0.14);
}

.ship-display-panel {
  flex: 0 0 165px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hud-ship-image {
  max-width: 100%;
  max-height: 145px;
  object-fit: contain;
  display: block;
}

.hud-panel {
  min-width: 150px;
  flex: 1 1 0;
}

.target-panel {
  flex: 1.25 1 0;
}

.hud-panel h3 {
  margin: 0 0 8px;
  font-size: 15px;
  color: #dff4ff;
  letter-spacing: 0.5px;
}

.hud-text {
  color: #d4e3f9;
  font-size: 13px;
  line-height: 1.45;
  min-height: 45px;
}

.hud-row {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}

.hud-row button,
#collectBtn {
  min-height: 38px;
  padding: 9px 10px;
  font-size: 12px;
}

@media (max-width: 900px) {
  .hub-screen,
  .space-screen,
  .market-screen,
  .hangar-screen {
    height: 90vh;
  }

  .hub-actions,
  .market-goods,
  .hangar-layout {
    grid-template-columns: 1fr;
  }

  .space-combat-hud {
    flex-wrap: wrap;
  }
}


/* ===== Target/HUD tidy-up + pulse lasers ===== */

.laser-layer {
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
}

.explosion-layer {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
}

.combat-fx-layer {
  position: absolute;
  inset: 0;
  z-index: 9;
  width: 100%;
  height: 100%;
  pointer-events: none;
  overflow: hidden;
  mix-blend-mode: screen;
}

.combat-fx-shot {
  opacity: 0;
  animation: combatFxShotFade 520ms ease-out forwards;
}

.combat-fx-beam-glow,
.combat-fx-beam-core {
  stroke: var(--combat-fx-color, #55e8ff);
  stroke-linecap: round;
  pointer-events: none;
}

.combat-fx-beam-glow {
  stroke-width: 9;
  opacity: 0.36;
  filter: drop-shadow(0 0 7px var(--combat-fx-color, #55e8ff));
}

.combat-fx-beam-core {
  stroke-width: 2.4;
  opacity: 0.98;
  filter:
    drop-shadow(0 0 3px rgba(255, 255, 255, 0.9))
    drop-shadow(0 0 8px var(--combat-fx-color, #55e8ff));
}

.combat-fx-shot.is-bot-return {
  --combat-fx-color: #ff8756;
}

.combat-fx-impact {
  fill: rgba(255, 255, 255, 0.22);
  stroke: var(--combat-fx-color, #55e8ff);
  stroke-width: 2;
  opacity: 0.95;
  filter: drop-shadow(0 0 6px var(--combat-fx-color, #55e8ff));
  animation: combatFxImpactTap 520ms ease-out forwards;
}

.space-explosion {
  position: absolute;
  width: 76px;
  height: 76px;
  margin-left: -38px;
  margin-top: -38px;
  border-radius: 50%;
  background:
    radial-gradient(circle, rgba(255,245,180,0.95) 0%, rgba(255,180,70,0.9) 24%, rgba(255,92,24,0.75) 52%, rgba(255,92,24,0.25) 70%, rgba(255,92,24,0) 100%);
  box-shadow:
    0 0 18px rgba(255,214,92,0.95),
    0 0 36px rgba(255,120,32,0.75),
    0 0 62px rgba(255,82,20,0.4);
  transform: scale(0.2);
  opacity: 0;
  animation: explosionBloom 560ms ease-out forwards;
}

.space-explosion::before {
  content: "";
  position: absolute;
  inset: -16px;
  border-radius: 50%;
  border: 2px solid rgba(255,220,120,0.55);
  opacity: 0.7;
  animation: explosionRing 560ms ease-out forwards;
}

.laser-burst {
  position: absolute;
  left: 265px;
  bottom: 150px;
  width: 430px;
  height: 4px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(80, 255, 170, 0), rgba(80, 255, 170, 1), rgba(80, 255, 170, 0.35));
  box-shadow:
    0 0 8px rgba(80, 255, 170, 0.95),
    0 0 18px rgba(80, 255, 170, 0.55);
  transform: rotate(-18deg);
  transform-origin: left center;
  opacity: 0;
  animation: laserBurst 220ms ease-out forwards;
}

.laser-burst.secondary {
  bottom: 142px;
  transform: rotate(-14deg);
  animation-delay: 30ms;
}

.laser-burst.player-shot {
  animation-timing-function: cubic-bezier(0.18, 0.88, 0.26, 1);
  mix-blend-mode: screen;
}

.laser-burst.simple-combat-laser {
  position: absolute;
  bottom: auto;
  border-radius: 999px;
  transform-origin: 0 50%;
  background: linear-gradient(90deg, rgba(86, 224, 255, 0), rgba(92, 229, 255, 0.95) 12%, rgba(255, 255, 255, 0.98) 50%, rgba(72, 210, 255, 0.85) 82%, rgba(72, 210, 255, 0));
  box-shadow:
    0 0 9px rgba(105, 232, 255, 0.72),
    0 0 18px rgba(50, 205, 255, 0.32);
  opacity: 0;
  mix-blend-mode: screen;
  animation: simpleCombatLaser 210ms ease-out forwards;
}

.laser-burst.simple-combat-laser.enemy-incoming-laser {
  background: linear-gradient(90deg, rgba(255, 90, 72, 0), rgba(255, 134, 76, 0.94) 14%, rgba(255, 238, 188, 0.98) 50%, rgba(255, 86, 68, 0.82) 82%, rgba(255, 86, 68, 0));
  box-shadow:
    0 0 9px rgba(255, 130, 82, 0.64),
    0 0 18px rgba(255, 68, 58, 0.28);
}

.weapon-muzzle-flash.simple-combat-muzzle {
  width: 18px;
  height: 18px;
  margin-left: -9px;
  margin-top: -9px;
}

.laser-burst.player-shot-polished {
  overflow: visible;
  filter: saturate(1.08) brightness(1.02);
}

.laser-burst.player-shot-polished::before,
.laser-burst.player-shot-polished::after {
  content: "";
  position: absolute;
  left: 3%;
  right: 5%;
  top: 50%;
  transform: translateY(-50%);
  border-radius: 999px;
  pointer-events: none;
}

.laser-burst.player-shot-polished::before {
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.88) 22%, rgba(255, 255, 255, 0.84) 58%, transparent);
  box-shadow: 0 0 4px rgba(240, 255, 255, 0.48);
}

.laser-burst.player-shot-polished::after {
  height: 7px;
  background: linear-gradient(90deg, transparent, var(--laser-glow-color, rgba(112, 232, 255, 0.22)) 20%, rgba(112, 232, 255, 0.14) 70%, transparent);
  opacity: 0.42;
  filter: blur(1px);
}

.weapon-muzzle-flash {
  position: absolute;
  width: 22px;
  height: 22px;
  margin-left: -11px;
  margin-top: -11px;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.86), var(--weapon-muzzle-color, #7fd6ff) 34%, transparent 68%);
  box-shadow:
    0 0 8px var(--weapon-muzzle-color, #7fd6ff),
    0 0 15px color-mix(in srgb, var(--weapon-muzzle-color, #7fd6ff) 42%, transparent);
  mix-blend-mode: screen;
  opacity: 0;
  animation: weaponMuzzleFlash 260ms ease-out forwards;
}

.player-shot-rapid {
  opacity: 0.94;
}

.player-shot-ion {
  filter: saturate(1.35) drop-shadow(0 0 5px rgba(210, 250, 255, 0.54));
}

.player-shot-melt,
.player-shot-heavy {
  filter: saturate(1.16) drop-shadow(0 0 7px rgba(255, 210, 130, 0.46));
}

.player-shot-sniper {
  filter: drop-shadow(0 0 9px rgba(190, 116, 255, 0.62));
}

.player-shot-disruptor,
.player-shot-ripper {
  filter: saturate(1.24) drop-shadow(0 0 7px rgba(56, 242, 166, 0.5));
}

.weapon-impact {
  position: absolute;
  width: 28px;
  height: 28px;
  margin-left: -14px;
  margin-top: -14px;
  border-radius: 50%;
  pointer-events: none;
  background:
    radial-gradient(circle, rgba(255, 255, 255, 0.82) 0 10%, var(--weapon-impact-color, #7fd6ff) 12% 28%, transparent 62%);
  box-shadow:
    0 0 7px var(--weapon-impact-color, #7fd6ff),
    0 0 14px color-mix(in srgb, var(--weapon-impact-color, #7fd6ff) 42%, transparent);
  opacity: 0;
  transform: scale(0.34);
  animation: weaponImpactFlash 180ms ease-out forwards;
}

.weapon-impact::after {
  display: none;
}

.weapon-impact-sniper {
  width: 52px;
  height: 52px;
  margin-left: -26px;
  margin-top: -26px;
}

@keyframes weaponImpactFlash {
  0% {
    opacity: 0;
    transform: scale(0.24);
  }

  30% {
    opacity: 0.95;
    transform: scale(0.82);
  }

  100% {
    opacity: 0;
    transform: scale(1.12);
  }
}

@keyframes combatFxShotFade {
  0% {
    opacity: 0;
  }

  12% {
    opacity: 1;
  }

  72% {
    opacity: 1;
  }

  100% {
    opacity: 0;
  }
}

@keyframes combatFxImpactTap {
  0% {
    opacity: 0;
    r: 3;
  }

  18% {
    opacity: 1;
    r: 8;
  }

  100% {
    opacity: 0;
    r: 11;
  }
}

@keyframes simpleCombatLaser {
  0% {
    opacity: 0;
    filter: brightness(1.18);
  }

  18% {
    opacity: 1;
    filter: brightness(1.2);
  }

  100% {
    opacity: 0;
    filter: brightness(0.96);
  }
}

@keyframes weaponImpactRing {
  0% {
    opacity: 0.75;
    transform: scale(0.48);
  }

  100% {
    opacity: 0;
    transform: scale(1.8);
  }
}

@keyframes weaponMuzzleFlash {
  0% {
    opacity: 0;
    transform: scale(0.38);
  }

  28% {
    opacity: 1;
    transform: scale(1);
  }

  100% {
    opacity: 0;
    transform: scale(1.25);
  }
}

@keyframes laserBurst {
  0% {
    opacity: 0;
    transform: rotate(var(--laser-angle, 0deg)) scaleX(0.98);
  }
  20% {
    opacity: 1;
    transform: rotate(var(--laser-angle, 0deg)) scaleX(1);
  }
  100% {
    opacity: 0;
    transform: rotate(var(--laser-angle, 0deg)) scaleX(1);
  }
}

.asteroid-target.weapon-hit-react img {
  animation: weaponTargetHitReact 160ms ease-out;
}

@keyframes weaponTargetHitReact {
  0% {
    filter: brightness(1) drop-shadow(0 0 0 rgba(255, 255, 255, 0));
    transform: translate3d(0, 0, 0) scale(1);
  }

  36% {
    filter: brightness(1.7) drop-shadow(0 0 12px rgba(255, 255, 255, 0.72));
    transform: translate3d(1px, -1px, 0) scale(1.025);
  }

  100% {
    filter: brightness(1) drop-shadow(0 0 0 rgba(255, 255, 255, 0));
    transform: translate3d(0, 0, 0) scale(1);
  }
}

