/* ===== Enemy incoming fire + repair panel ===== */

.enemy-incoming-laser {
  height: 5px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(255, 86, 46, 0), rgba(255, 68, 42, 0.92) 14%, rgba(255, 245, 190, 1) 44%, rgba(255, 170, 50, 0.86) 68%, rgba(255, 70, 44, 0));
  box-shadow:
    0 0 8px rgba(255, 232, 146, 0.84),
    0 0 17px rgba(255, 116, 48, 0.72),
    0 0 32px rgba(255, 64, 48, 0.36);
  transform-origin: left center;
  transform: rotate(var(--incoming-angle, 0deg)) translateX(0);
  mix-blend-mode: screen;
  animation: incomingLaserBurst 440ms ease-out forwards;
}

.enemy-incoming-laser-burst {
  height: 3px;
}

.enemy-incoming-laser-heavy {
  height: 7px;
  box-shadow:
    0 0 10px rgba(255, 244, 186, 0.92),
    0 0 24px rgba(255, 94, 42, 0.78),
    0 0 46px rgba(255, 42, 36, 0.42);
}

@keyframes incomingLaserBurst {
  0% {
    opacity: 0;
    clip-path: inset(0 100% 0 0);
    transform: rotate(var(--incoming-angle, 0deg)) translateX(0) scaleX(0.72);
  }

  14% {
    opacity: 1;
    clip-path: inset(0 0 0 0);
    transform: rotate(var(--incoming-angle, 0deg)) translateX(calc(var(--incoming-travel, 120px) * 0.16)) scaleX(1);
  }

  100% {
    opacity: 0;
    clip-path: inset(0 0 0 18%);
    transform: rotate(var(--incoming-angle, 0deg)) translateX(var(--incoming-travel, 120px)) scaleX(0.86);
  }
}

.incoming-hit-flash::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 13;
  animation: pilotHitFlash 240ms ease-out forwards;
}

.incoming-hit-flash.shield-impact::after {
  background:
    radial-gradient(ellipse at 50% 90%, rgba(95, 221, 255, 0.20), transparent 30%),
    radial-gradient(ellipse at 50% 100%, transparent 44%, rgba(84, 210, 255, 0.30) 72%, transparent 100%),
    linear-gradient(90deg, rgba(86, 211, 255, 0.23), transparent 16%, transparent 84%, rgba(86, 211, 255, 0.23)),
    linear-gradient(180deg, rgba(86, 211, 255, 0.12), transparent 20%, transparent 76%, rgba(86, 211, 255, 0.17));
}

.incoming-hit-flash.armor-impact::after {
  background:
    radial-gradient(ellipse at 50% 90%, rgba(232, 229, 205, 0.18), transparent 30%),
    radial-gradient(ellipse at 50% 100%, transparent 46%, rgba(224, 219, 190, 0.24) 74%, transparent 100%),
    repeating-linear-gradient(105deg, rgba(255, 221, 132, 0.18) 0 2px, transparent 2px 18px),
    linear-gradient(90deg, rgba(218, 222, 205, 0.16), transparent 17%, transparent 83%, rgba(218, 222, 205, 0.16));
}

.incoming-hit-flash.hull-impact::after {
  background:
    radial-gradient(ellipse at 50% 90%, rgba(255, 126, 72, 0.24), transparent 31%),
    radial-gradient(ellipse at 50% 100%, transparent 44%, rgba(255, 88, 58, 0.34) 74%, transparent 100%),
    linear-gradient(90deg, rgba(255, 92, 64, 0.28), transparent 15%, transparent 85%, rgba(255, 92, 64, 0.28)),
    linear-gradient(180deg, rgba(255, 95, 64, 0.14), transparent 20%, transparent 74%, rgba(255, 76, 62, 0.22));
}

@keyframes pilotHitFlash {
  0% { opacity: 0; }
  28% { opacity: 1; }
  100% { opacity: 0; }
}

.hud-hit-flash {
  animation: hudHitFlash 240ms ease-out forwards;
}

.hud-hit-flash.shield-impact {
  --hud-hit-rgb: 93, 216, 255;
}

.hud-hit-flash.armor-impact {
  --hud-hit-rgb: 225, 219, 190;
}

.hud-hit-flash.hull-impact {
  --hud-hit-rgb: 255, 95, 80;
}

.vertical-stats.player-shield-depleted {
  box-shadow:
    0 0 14px rgba(79, 220, 255, 0.34),
    inset 0 0 16px rgba(79, 220, 255, 0.08);
}

.vertical-stats.player-hull-critical {
  animation: playerHullCriticalPulse 1.15s ease-in-out infinite;
}

.vertical-stats.player-hull-disabled-threshold {
  animation: playerHullCriticalPulse 0.9s ease-in-out infinite;
}

.player-hull-critical .hull-fill {
  filter: saturate(1.25) brightness(1.1) drop-shadow(0 0 6px rgba(255, 62, 58, 0.72));
}

.player-hull-disabled-threshold .hull-fill {
  filter: saturate(1.45) brightness(1.18) drop-shadow(0 0 8px rgba(255, 62, 58, 0.86));
}

.player-shield-depleted .shield-fill {
  opacity: 0.54;
  filter: drop-shadow(0 0 5px rgba(76, 220, 255, 0.48));
}

@keyframes hudHitFlash {
  0% {
    box-shadow: 0 0 0 rgba(var(--hud-hit-rgb, 255, 95, 80), 0);
  }

  25% {
    box-shadow:
      0 0 12px rgba(var(--hud-hit-rgb, 255, 95, 80), 0.56),
      inset 0 0 14px rgba(var(--hud-hit-rgb, 255, 95, 80), 0.13);
  }

  100% {
    box-shadow: 0 0 0 rgba(var(--hud-hit-rgb, 255, 95, 80), 0);
  }
}

@keyframes playerHullCriticalPulse {
  0%, 100% {
    box-shadow:
      0 0 0 rgba(255, 72, 60, 0),
      inset 0 0 0 rgba(255, 72, 60, 0);
  }

  50% {
    box-shadow:
      0 0 14px rgba(255, 72, 60, 0.4),
      inset 0 0 16px rgba(255, 72, 60, 0.12);
  }
}

.incoming-impact-shake {
  animation: hostileImpactJolt 230ms ease-out;
}

@keyframes hostileImpactJolt {
  0% { transform: translate3d(0, 0, 0); }
  28% { transform: translate3d(-1.25px, 1px, 0); }
  58% { transform: translate3d(1.2px, -1.15px, 0); }
  80% { transform: translate3d(-0.55px, 0.45px, 0); }
  100% { transform: translate3d(0, 0, 0); }
}

