  border-radius: 6px;
  background: rgba(0,0,0,0.35);
}

.salvage-resource-chip strong,
.salvage-resource-chip span {
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.salvage-resource-chip strong {
  color: #eaf3ff;
  font-size: 11px;
  line-height: 1.05;
}

.salvage-resource-chip span {
  color: #9fb7d7;
  font-size: 10px;
  line-height: 1.05;
}

.salvage-resource-chip button {
  min-height: 24px;
  padding: 3px 5px;
  font-size: 10px;
  border-radius: 8px;
}

/* Inventory HUD */

.inventory-hud {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 6px;
}

.inventory-hud-top {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 10px;
}

.inventory-hud-top strong {
  display: block;
  color: #eaf3ff;
  font-size: 13px;
  margin-top: 2px;
}

.inventory-future-note {
  color: #9fb7d7;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.7px;
}

.cargo-inventory-grid {
  min-height: 0;
  overflow-y: auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 7px;
  padding-right: 5px;
  align-content: start;
}

.cargo-resource-card {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  padding: 5px 6px;
  border: 1px solid rgba(90, 190, 255, 0.24);
  border-radius: 10px;
  background:
    radial-gradient(circle at 0% 50%, rgba(80, 180, 255, 0.10), transparent 44%),
    rgba(7, 18, 34, 0.66);
}

.cargo-resource-card img {
  width: 30px;
  height: 30px;
  object-fit: contain;
  border-radius: 7px;
  background: rgba(0,0,0,0.36);
}

.cargo-resource-info {
  min-width: 0;
  display: grid;
  gap: 1px;
}

.cargo-resource-info strong,
.cargo-resource-info span {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cargo-resource-info strong {
  color: #eaf3ff;
  font-size: 11px;
}

.cargo-resource-info span {
  color: #9fb7d7;
  font-size: 10px;
}

.cargo-resource-actions {
  display: flex;
  gap: 4px;
  flex-wrap: nowrap;
}

.cargo-resource-actions button {
  min-height: 24px;
  padding: 3px 6px;
  font-size: 9px;
  border-radius: 8px;
  white-space: nowrap;
}

.cargo-resource-actions button:last-child {
  border-color: rgba(255, 120, 90, 0.7);
  color: #ffd5cc;
}

.cargo-empty {
  color: #9fb7d7;
  font-size: 12px;
  padding: 6px 0;
}

.cargo-inventory-grid,
.salvage-list {
  scrollbar-width: thin;
  scrollbar-color: rgba(116, 219, 255, 0.92) rgba(10, 22, 40, 0.45);
}

.cargo-inventory-grid::-webkit-scrollbar {
  width: 7px;
}

.cargo-inventory-grid::-webkit-scrollbar-track {
  background: rgba(10, 22, 40, 0.45);
  border-radius: 999px;
}

.cargo-inventory-grid::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, rgba(120, 225, 255, 0.95), rgba(50, 110, 220, 0.92));
  border-radius: 999px;
}

@media (max-width: 1100px) {
  .sector-panel-layout {
    grid-template-columns: 130px minmax(240px, 1fr) 110px !important;
  }

  .cargo-inventory-grid {
    grid-template-columns: 1fr;
  }
}


