/* ===== Bounty board foundation ===== */
.hub-actions {
  grid-template-columns: repeat(4, 1fr);
}

.bounty-screen {
  background:
    radial-gradient(circle at 18% 24%, rgba(255, 70, 110, 0.10), transparent 26%),
    radial-gradient(circle at 76% 18%, rgba(36, 143, 220, 0.12), transparent 30%),
    linear-gradient(to bottom, rgba(2,5,11,0.91), rgba(2,5,11,0.98)),
    url("asteron-prime-space-station-hub.png");
  background-size: cover;
  background-position: center;
}

.bounty-board-layout {
  height: calc(100% - 84px);
  display: grid;
  grid-template-columns: 260px minmax(390px, 1fr) 300px;
  gap: 14px;
  min-height: 0;
}

.bounty-board-summary,
.bounty-contract-panel,
.bounty-detail-panel {
  min-width: 0;
  min-height: 0;
}

.bounty-board-summary {
  display: grid;
  align-content: start;
  gap: 12px;
}

.bounty-board-summary p {
  font-size: 0.82rem;
}

.bounty-board-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border: 1px solid rgba(90, 190, 255, 0.16);
  border-radius: 10px;
  padding: 10px;
  background: rgba(2, 8, 18, 0.64);
}

.bounty-board-meta span {
  color: #7fdfff;
  font-weight: 900;
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.bounty-board-meta strong {
  color: #f1f8ff;
}

.bounty-contract-panel,
.bounty-detail-panel {
  background: rgba(0, 0, 0, 0.66);
  border: 1px solid rgba(90, 190, 255, 0.62);
  border-radius: 14px;
  box-shadow: inset 0 1px 0 rgba(160, 230, 255, 0.08), 0 0 24px rgba(0, 160, 255, 0.08);
  overflow: hidden;
  display: grid;
  grid-template-rows: auto 1fr;
}

.bounty-panel-header em {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 4px 10px;
  border: 1px solid rgba(255, 211, 107, 0.34);
  border-radius: 999px;
  background: rgba(58, 40, 8, 0.32);
  color: #ffd36b;
  font-style: normal;
  font-size: 0.7rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-shadow: 0 0 10px rgba(255, 190, 75, 0.34);
  text-transform: uppercase;
}

.bounty-contract-grid {
  padding: 12px;
  display: grid;
  grid-template-rows: repeat(3, minmax(82px, 1fr));
  gap: 10px;
  min-height: 0;
}

.bounty-contract-card {
  width: 100%;
  min-height: 0;
  padding: 10px;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  grid-template-rows: 1fr auto;
  align-items: center;
  gap: 6px 10px;
  text-align: left;
  border: 1px solid rgba(90, 190, 255, 0.36);
  border-radius: 12px;
  background:
    radial-gradient(circle at 8% 16%, rgba(255, 83, 112, 0.16), transparent 36%),
    rgba(5, 14, 26, 0.84);
}

.bounty-contract-card:hover,
.bounty-contract-card.selected {
  border-color: rgba(127, 223, 255, 0.9);
  box-shadow: 0 0 18px rgba(0, 170, 255, 0.16);
}

.bounty-contract-card.completed {
  opacity: 0.76;
  border-color: rgba(101, 240, 160, 0.42);
  background:
    radial-gradient(circle at 8% 16%, rgba(101, 240, 160, 0.12), transparent 36%),
    rgba(5, 14, 26, 0.78);
}

.bounty-contract-card.completed .bounty-card-status {
  border-color: rgba(101, 240, 160, 0.48);
  background: rgba(18, 58, 38, 0.64);
  color: #65f0a0;
  box-shadow: 0 0 14px rgba(101, 240, 160, 0.16);
}

.bounty-card-icon,
.bounty-detail-icon,
.objective-bounty-icon {
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 90, 125, 0.55);
  background: rgba(52, 5, 18, 0.62);
  color: #ff8fa7;
  box-shadow: 0 0 14px rgba(255, 60, 100, 0.16);
}

.bounty-card-icon {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  grid-row: 1 / 3;
}

.bounty-card-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.bounty-card-copy strong {
  color: #f1f8ff;
  font-size: 0.88rem;
  line-height: 1.05;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bounty-card-copy em {
  color: #a9c0da;
  font-style: normal;
  font-size: 0.7rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bounty-card-reward {
  color: #65f0a0;
  font-weight: 900;
  font-size: 0.82rem;
  justify-self: end;
}

.bounty-card-status {
  grid-column: 2 / 4;
  width: fit-content;
  border: 1px solid rgba(127, 223, 255, 0.18);
  border-radius: 999px;
  padding: 3px 8px;
  color: #7fdfff;
  background: rgba(0,0,0,0.22);
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.bounty-detail-body {
  padding: 12px;
  display: grid;
  align-content: start;
  gap: 10px;
  min-height: 0;
}

.bounty-detail-hero {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid rgba(90, 190, 255, 0.16);
}

.bounty-detail-icon,
.objective-bounty-icon {
  width: 42px;
  height: 42px;
  min-width: 42px;
  border-radius: 12px;
  font-weight: 900;
}

.bounty-detail-hero strong {
  display: block;
  color: #f1f8ff;
  margin-bottom: 3px;
}

.bounty-detail-hero span,
.bounty-detail-note {
  color: #a9c0da;
  font-size: 0.74rem;
  line-height: 1.35;
}

.bounty-detail-stat {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  border: 1px solid rgba(90, 190, 255, 0.16);
  border-radius: 10px;
  padding: 9px 10px;
  background: rgba(2, 8, 18, 0.58);
}

.bounty-detail-stat span {
  color: #7fdfff;
  font-size: 0.64rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.bounty-detail-stat strong {
  color: #f1f8ff;
  font-size: 0.78rem;
  text-align: right;
}

.bounty-accept-btn {
  min-height: 42px;
}

.bounty-objective-card {
  border-color: rgba(255, 90, 125, 0.42);
  background:
    radial-gradient(circle at 15% 10%, rgba(255, 83, 112, 0.16), transparent 34%),
    rgba(2, 12, 20, 0.78);
}

.bounty-pill {
  color: #ff8fa7;
}

@media (max-width: 900px) {
  .hub-actions {
    grid-template-columns: 1fr;
  }

  .bounty-board-layout {
    grid-template-columns: 1fr;
    overflow-y: auto;
  }

  .bounty-contract-grid {
    grid-template-rows: none;
  }
}

.bounty-cancel-btn {
  margin-top: 9px;
  background: rgba(95, 22, 32, 0.86);
  border: 1px solid rgba(255, 118, 132, 0.62);
  color: #ffe5e8;
}

.bounty-cancel-btn:hover {
  background: rgba(135, 35, 48, 0.94);
}

.bounty-cancel-btn {
  margin-top: 9px;
  background: rgba(95, 22, 32, 0.86);
  border: 1px solid rgba(255, 118, 132, 0.62);
  color: #ffe5e8;
}

.bounty-cancel-btn:hover {
  background: rgba(135, 35, 48, 0.94);
}

/* ===== Objectives separated from Activity HUD tab ===== */
.objectives-panel,
.activity-panel {
  min-height: 0;
}

.objective-panel-layout {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}

.objectives-panel .activity-objective-block {
  min-height: 0;
  display: grid;
  grid-template-rows: auto 1fr;
}

.objectives-panel .objective-hud-summary {
  min-height: 0;
  height: 100%;
  overflow: hidden;
}

.objectives-panel .objective-hud-card {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: auto 1fr auto;
  align-content: start;
  padding: 10px;
}

.objectives-panel .objective-main-row {
  align-self: center;
}

.objectives-panel .objective-bounty-icon,
.objectives-panel .objective-icon {
  width: 44px;
  height: 44px;
  min-width: 44px;
}

.objectives-panel .objective-copy strong {
  font-size: 0.92rem;
}

.objectives-panel .objective-copy span {
  font-size: 0.76rem;
}

.objectives-panel .objective-mini-stats span {
  font-size: 0.68rem;
  padding: 5px 8px;
}

.activity-log-only-block {
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: auto 1fr;
}

.activity-panel .activity-log-feed {
  height: 100%;
  min-height: 0;
  max-height: none;
  overflow-y: auto;
}

.activity-panel .activity-log-item {
  padding: 5px 0 6px;
}

/* ===== Bounty reward claim flow ===== */
.hub-actions button {
  position: relative;
  overflow: hidden;
}

.hub-action-badge {
  display: none;
  position: absolute;
  right: 10px;
  top: 8px;
  align-items: center;
  justify-content: center;
  padding: 4px 7px;
  border-radius: 999px;
  background: rgba(255, 210, 84, 0.16);
  border: 1px solid rgba(255, 210, 84, 0.78);
  color: #ffe58c;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.7px;
  text-transform: uppercase;
  box-shadow: 0 0 16px rgba(255, 210, 84, 0.28);
}

.hub-actions button.reward-ready {
  border-color: rgba(255, 210, 84, 0.9);
  box-shadow: 0 0 22px rgba(255, 210, 84, 0.22), 0 0 34px rgba(0, 180, 255, 0.12);
}

.bounty-contract-card.ready-to-claim {
  border-color: rgba(255, 210, 84, 0.9);
  box-shadow: 0 0 22px rgba(255, 210, 84, 0.16), inset 0 1px 0 rgba(255, 235, 160, 0.12);
}

.bounty-detail-hero.reward-ready {
  border: 1px solid rgba(255, 210, 84, 0.62);
  background: linear-gradient(135deg, rgba(255, 210, 84, 0.1), rgba(0, 160, 255, 0.04));
  border-radius: 13px;
  padding: 12px;
}

.bounty-detail-hero.completed {
  border: 1px solid rgba(101, 240, 160, 0.34);
  background: linear-gradient(135deg, rgba(101, 240, 160, 0.08), rgba(0, 160, 255, 0.03));
}

.bounty-claim-btn {
  margin-top: 12px;
  background: linear-gradient(135deg, #d9a726, #7f4e00);
  border: 1px solid rgba(255, 232, 145, 0.78);
  box-shadow: 0 0 18px rgba(255, 210, 84, 0.22);
}

.bounty-claim-btn:hover {
  background: linear-gradient(135deg, #f0bd3a, #9b6207);
}

.reward-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(circle at center, rgba(255, 210, 84, 0.08), rgba(0, 0, 0, 0.72));
  transition: opacity 180ms ease;
}

.reward-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.reward-overlay.tutorial-reward-active {
  z-index: 999;
}

.reward-modal {
  width: min(460px, calc(100vw - 32px));
  background: rgba(4, 12, 24, 0.96);
  border: 1px solid rgba(127, 223, 255, 0.72);
  border-radius: 18px;
  padding: 24px;
  text-align: center;
  box-shadow: 0 0 48px rgba(0, 160, 255, 0.24), 0 0 28px rgba(255, 210, 84, 0.16);
  transform: translateY(12px) scale(0.96);
  animation: rewardModalIn 340ms ease forwards;
}

.reward-kicker {
  color: #7fdfff;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.reward-modal h2 {
  margin: 8px 0 16px;
  font-size: 24px;
}

.reward-credit-pulse {
  margin: 0 auto 18px;
  padding: 14px 18px;
  width: fit-content;
  border-radius: 999px;
  color: #ffe58c;
  font-size: 28px;
  font-weight: 1000;
  letter-spacing: 1px;
  background: rgba(255, 210, 84, 0.1);
  border: 1px solid rgba(255, 210, 84, 0.55);
  box-shadow: 0 0 26px rgba(255, 210, 84, 0.24);
  animation: rewardCreditPulse 900ms ease-in-out infinite alternate;
}

.reward-loot-list {
  display: grid;
  gap: 10px;
  margin-bottom: 18px;
}

.reward-loot-card,
.reward-no-loot {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 9px 12px;
  border-radius: 12px;
  background: rgba(7, 18, 34, 0.82);
  border: 1px solid rgba(127, 223, 255, 0.32);
  color: #dff4ff;
  font-size: 13px;
  font-weight: 900;
}

.reward-loot-card img {
  width: 32px;
  height: 32px;
  object-fit: contain;
}

.reward-modal button {
  max-width: 220px;
  margin: 0 auto;
}

@keyframes rewardModalIn {
  to { transform: translateY(0) scale(1); }
}

@keyframes rewardCreditPulse {
  from { transform: scale(1); filter: brightness(1); }
  to { transform: scale(1.035); filter: brightness(1.2); }
}

/* ===== Ship disabled / hangar repair consequence ===== */
.repair-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  pointer-events: none;
  opacity: 0;
  background:
    radial-gradient(circle at center, rgba(255, 84, 112, 0.12), rgba(0, 0, 0, 0.76));
  transition: opacity 180ms ease;
}

.repair-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.repair-modal {
  width: min(470px, calc(100vw - 32px));
  background: rgba(4, 12, 24, 0.97);
  border: 1px solid rgba(255, 84, 112, 0.72);
  border-radius: 18px;
  padding: 24px;
  text-align: center;
  box-shadow:
    0 0 48px rgba(255, 84, 112, 0.2),
    0 0 30px rgba(0, 160, 255, 0.12);
  transform: translateY(12px) scale(0.96);
  animation: rewardModalIn 340ms ease forwards;
}

.danger-kicker {
  color: #ff8aa2;
}

.repair-modal h2 {
  margin: 8px 0 12px;
  font-size: 25px;
}

.repair-modal p {
  margin: 0 0 14px;
  color: #d5e2f5;
  line-height: 1.45;
}

.repair-modal-stat,
.repair-loss-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(7, 18, 34, 0.82);
  border: 1px solid rgba(127, 223, 255, 0.28);
  color: #dff4ff;
  font-size: 13px;
}

.repair-modal-stat {
  margin-bottom: 10px;
  border-color: rgba(255, 84, 112, 0.48);
}

.repair-modal-stat strong,
.repair-loss-row strong {
  color: #ffb6c4;
}

.repair-loss-list {
  display: grid;
  gap: 8px;
  margin-bottom: 16px;
}

.repair-loss-row.muted strong {
  color: #7fdfff;
}

.repair-modal-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.repair-modal-actions button {
  min-height: 42px;
}

@media (max-width: 640px) {
  .repair-modal-actions {
    grid-template-columns: 1fr;
  }
}

/* ===== Pilot / Skill XP Foundation ===== */
.hud-progress-strip {
  display: grid;
  grid-template-columns: 58px 1fr 1fr;
  gap: 7px;
  align-items: center;
  margin-bottom: 7px;
  min-height: 34px;
}

.hud-pilot-level,
.mini-xp-card {
  background: rgba(5, 14, 28, 0.86);
  border: 1px solid rgba(127, 223, 255, 0.28);
  border-radius: 9px;
  box-shadow: inset 0 1px 0 rgba(160, 230, 255, 0.08);
}

.hud-pilot-level {
  height: 34px;
  display: grid;
  place-items: center;
  line-height: 1;
}

.hud-pilot-level span {
  color: #7fdfff;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.7px;
}

.hud-pilot-level strong {
  color: #fff;
  font-size: 15px;
}

.mini-xp-card {
  padding: 5px 7px;
  display: grid;
  gap: 2px;
  min-width: 0;
}

.mini-xp-card span,
.mini-xp-card em {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mini-xp-card span {
  color: #dff4ff;
  font-size: 10px;
  font-weight: 900;
}

.mini-xp-card em {
  color: #8da7c9;
  font-size: 8.5px;
  font-style: normal;
}

.mini-xp-track,
.profile-xp-track {
  height: 5px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255,255,255,0.11);
  box-shadow: inset 0 0 8px rgba(0,0,0,0.5);
}

.mini-xp-track i,
.profile-xp-track i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(127,223,255,0.9), rgba(255,214,92,0.95));
  box-shadow: 0 0 12px rgba(127,223,255,0.45);
}

.pilot-profile-body {
  height: calc(100% - 84px);
