.market-board-table th:not(:first-child),
.market-board-table td:not(:first-child) {
  width: 22%;
}

.market-board-table th,
.market-board-table td {
  padding: 14px 12px;
  border-bottom: 1px solid rgba(90, 190, 255, 0.14);
  text-align: left;
  color: #dbeeff;
  white-space: nowrap;
}

.market-board-table th {
  color: #7fdfff;
  font-size: 0.62rem;
  font-weight: 950;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: rgba(2, 8, 18, 0.82);
  position: sticky;
  top: 0;
  z-index: 1;
}

.market-board-table tbody td {
  font-size: 0.88rem;
  font-weight: 800;
}

.market-board-table tbody tr:last-child td {
  border-bottom: 0;
}

.market-board-table tbody tr {
  cursor: pointer;
  transition: background 160ms ease, box-shadow 160ms ease, color 160ms ease;
}

.market-board-table tbody tr:nth-child(even) {
  background: rgba(20, 62, 96, 0.08);
}

.market-board-table tbody tr:hover,
.market-board-table tbody tr.selected-market-row {
  background: rgba(48, 145, 220, 0.16);
  box-shadow: inset 4px 0 0 rgba(127, 223, 255, 0.9);
}

.market-resource-cell {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.market-board-icon,
.market-builder-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  border-radius: 8px;
}

.current-market-planet {
  color: #f1f8ff !important;
  background: rgba(127, 223, 255, 0.08);
}

.market-builder-panel {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  gap: 7px;
  padding: 10px;
  overflow: hidden;
}

.market-builder-selected {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}

.market-builder-selected h3 {
  margin: 0 0 2px;
  color: #f1f8ff;
  font-size: 1rem;
  line-height: 1.05;
}

.market-builder-selected p {
  margin: 0;
  color: #9ebcda;
  font-size: 0.66rem;
}

.market-builder-controls {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}

.market-builder-controls--routes {
  min-height: 0;
  grid-template-rows: minmax(0, 1fr) auto;
}

.market-builder-controls label {
  display: grid;
  gap: 5px;
  color: #7fdfff;
  font-size: 0.6rem;
  font-weight: 950;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.market-builder-controls select,
.market-builder-controls input {
  width: 100%;
  min-height: 30px;
  border: 1px solid rgba(90, 190, 255, 0.28);
  border-radius: 8px;
  background: rgba(2, 8, 18, 0.86);
  color: #f1f8ff;
  font-family: inherit;
  font-size: 0.82rem;
}

.market-target-confirm {
  min-height: 30px;
  border: 1px solid rgba(127, 223, 255, 0.32);
  border-radius: 8px;
  background: rgba(7, 26, 46, 0.92);
  color: #d9f7ff;
  font-family: inherit;
  font-size: 0.68rem;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
}

.market-target-confirm:hover {
  border-color: rgba(127, 223, 255, 0.72);
  color: #ffffff;
}

.market-amount-control {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 62px minmax(104px, 0.9fr);
  gap: 8px;
  align-items: stretch;
}

.market-amount-control--route {
  grid-template-columns: minmax(0, 1fr) 88px;
}

.market-amount-control strong,
.market-amount-control button {
  min-height: 34px;
  border-radius: 8px;
  font-family: inherit;
  font-size: 0.76rem;
  font-weight: 900;
}

.market-amount-control strong {
  display: grid;
  place-items: center;
  border: 1px solid rgba(127, 223, 255, 0.32);
  color: #f1f8ff;
  background: rgba(2, 8, 18, 0.86);
}

.market-amount-control button {
  border: 1px solid rgba(90, 190, 255, 0.24);
  color: #65f0a0;
  background: rgba(2, 18, 14, 0.78);
  cursor: pointer;
}

.market-amount-control .trade-primary-action {
  color: #fff;
  background: linear-gradient(180deg, rgba(42, 103, 190, 0.96), rgba(22, 85, 168, 0.96));
  border-color: rgba(127, 223, 255, 0.34);
}

.market-amount-control button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.trade-route-section {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 10px;
  min-height: 0;
}

.trade-route-section__head {
  color: #7fdfff;
  font-size: 0.62rem;
  font-weight: 950;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.trade-route-list {
  display: grid;
  grid-auto-rows: minmax(220px, 1fr);
  align-content: start;
  gap: 10px;
  min-height: 0;
  overflow: auto;
  padding-right: 2px;
}

.trade-route-card {
  display: grid;
  grid-template-columns: 116px minmax(0, 1fr);
  gap: 16px;
  width: 100%;
  height: 100%;
  min-height: 220px;
  padding: 16px 18px;
  box-sizing: border-box;
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(90, 190, 255, 0.36);
  border-radius: 8px;
  background:
    radial-gradient(circle at 12% 20%, rgba(72, 180, 255, 0.18), transparent 34%),
    linear-gradient(180deg, rgba(5, 18, 36, 0.94), rgba(2, 9, 20, 0.94));
  box-shadow: inset 0 1px 0 rgba(170, 235, 255, 0.08);
  cursor: pointer;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease, opacity 160ms ease;
}

.trade-route-card:hover,
.trade-route-card:focus-visible,
.trade-route-card.is-selected {
  border-color: rgba(127, 223, 255, 0.82);
  box-shadow: inset 0 1px 0 rgba(170, 235, 255, 0.12), 0 0 18px rgba(43, 171, 255, 0.2);
}

.trade-route-card.is-best {
  border-color: rgba(127, 223, 255, 0.92);
  box-shadow: inset 0 1px 0 rgba(170, 235, 255, 0.16), 0 0 22px rgba(43, 171, 255, 0.28);
}

.trade-route-card.is-loss,
.trade-route-card.is-muted {
  opacity: 0.72;
  border-color: rgba(115, 150, 180, 0.32);
  background: linear-gradient(180deg, rgba(7, 14, 24, 0.88), rgba(3, 8, 16, 0.9));
  box-shadow: none;
}

.trade-route-card__planet {
  width: 92px;
  height: 92px;
  align-self: center;
  border-radius: 50%;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 0 16px rgba(82, 190, 255, 0.36));
}

.trade-route-card__planet img {
  width: 92px;
  height: 92px;
  object-fit: contain;
  display: block;
}

.trade-route-card__main {
  min-width: 0;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: 9px;
  overflow: hidden;
}

.trade-route-card__title-row,
.trade-route-card__bottom {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.trade-route-card__bottom {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 176px;
  grid-template-areas:
    "profit action"
    "cargo action";
  align-items: stretch;
  gap: 7px 14px;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.trade-route-card__title {
  margin: 0 0 2px;
  color: #f1f8ff;
  font-size: 1.16rem;
  line-height: 1.05;
}

.trade-route-card__route {
  margin: 0;
  color: #9ebcda;
  font-size: 0.78rem;
}

.trade-route-badge {
  flex: 0 0 auto;
  padding: 6px 10px;
  border: 1px solid rgba(255, 215, 106, 0.52);
  border-radius: 6px;
  color: #ffe589;
  background: rgba(70, 46, 10, 0.52);
  font-size: 0.62rem;
  font-weight: 950;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.trade-route-card__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.trade-route-chip {
  padding: 6px 12px;
  border: 1px solid rgba(90, 190, 255, 0.24);
  border-radius: 5px;
  color: #dbeeff;
  background: rgba(3, 14, 28, 0.82);
  font-size: 0.72rem;
  font-weight: 850;
}

.trade-route-chip--profit {
  border-color: rgba(101, 240, 160, 0.28);
  color: #65f0a0;
  background: rgba(2, 32, 22, 0.72);
}

.trade-route-chip--loss {
  border-color: rgba(255, 106, 126, 0.32);
  color: #ff8e9f;
  background: rgba(45, 10, 18, 0.7);
}

.trade-route-chip--jumps {
  color: #b9d7f4;
}

.trade-route-chip--cost,
.trade-route-chip--revenue {
  color: #b9d7f4;
  border-color: rgba(90, 190, 255, 0.16);
  background: rgba(2, 8, 18, 0.56);
}

.trade-route-card__profit {
  grid-area: profit;
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
  align-self: start;
}

.trade-route-card__profit span {
  color: #9ebcda;
  font-size: 0.68rem;
  font-weight: 850;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.trade-route-card__profit strong {
  font-size: 1.18rem;
  line-height: 1.05;
  white-space: nowrap;
}

.trade-route-card__profit em {
  display: none;
}

.trade-route-card__cargo {
  grid-area: cargo;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 2px 8px;
  align-self: end;
  min-width: 0;
  margin-top: 0;
  padding-top: 8px;
  border-top: 1px solid rgba(127, 223, 255, 0.22);
  color: #b9d7f4;
  overflow: hidden;
}

.trade-route-card__cargo span {
  font-size: 0.82rem;
}

.trade-route-card__cargo strong {
  color: #f1f8ff;
  font-size: 0.9rem;
}

.trade-route-card__cargo em {
  display: block;
  grid-column: 1 / -1;
  color: #9ebcda;
  font-size: 0.62rem;
  font-style: normal;
  line-height: 1.25;
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.trade-route-card__button {
  grid-area: action;
  align-self: end;
  width: 176px;
  height: 64px;
  min-height: 64px;
  padding: 10px 16px;
  border-radius: 7px;
  font-size: 0.88rem;
}

.trade-route-card__button:disabled {
  cursor: not-allowed;
  opacity: 0.56;
  color: #b4bdc7;
  border-color: rgba(140, 160, 180, 0.26);
  background: linear-gradient(180deg, rgba(42, 48, 58, 0.88), rgba(22, 26, 34, 0.88));
}

.trade-route-empty {
  display: grid;
  gap: 6px;
  align-content: center;
  min-height: 180px;
  padding: 18px;
  border: 1px solid rgba(90, 190, 255, 0.22);
  border-radius: 8px;
  background: rgba(2, 8, 18, 0.62);
}

.trade-route-empty strong {
  color: #f1f8ff;
  font-size: 0.95rem;
}

.trade-route-empty span {
  color: #9ebcda;
  font-size: 0.76rem;
}

@keyframes tutorialLandingPulse {
  0%, 100% {
    filter: drop-shadow(0 0 6px rgba(127, 223, 255, 0.48));
    transform: scale(1);
  }
  50% {
    filter: drop-shadow(0 0 16px rgba(127, 223, 255, 0.86));
    transform: scale(1.045);
  }
}

.market-builder-summary,
.market-builder-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
  align-content: start;
  overflow: visible;
}

.market-builder-summary div,
.market-builder-stats div {
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid rgba(90, 190, 255, 0.16);
  border-radius: 8px;
  background: rgba(2, 8, 18, 0.62);
}

.market-builder-summary span,
.market-builder-stats span {
  display: block;
  margin-bottom: 1px;
  color: #95b6d8;
  font-size: 0.5rem;
  font-weight: 850;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.market-builder-summary strong,
.market-builder-stats strong {
  color: #f1f8ff;
  font-size: 0.76rem;
  overflow-wrap: anywhere;
}

.market-builder-summary .profit-summary-card {
  border-color: rgba(101, 240, 160, 0.28);
  background:
    radial-gradient(circle at 90% 20%, rgba(101, 240, 160, 0.12), transparent 48%),
    rgba(2, 18, 14, 0.58);
}

.market-builder-actions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
  align-items: stretch;
}

.market-builder-actions.no-sell {
  grid-template-columns: 1fr;
}

.market-builder-actions button {
  width: 100%;
  min-height: 36px;
  padding: 8px 10px;
}

.market-builder-panel.staging-sell-builder {
  gap: 6px;
  padding: 10px;
  align-content: start;
  grid-template-rows: none;
  grid-auto-rows: auto;
  overflow-y: auto;
}

.market-builder-panel.staging-sell-builder .market-builder-selected {
  gap: 7px;
}

.market-builder-panel.staging-sell-builder .market-builder-icon {
  width: 32px;
  height: 32px;
  flex-basis: 32px;
}

.market-builder-panel.staging-sell-builder .market-builder-controls {
  gap: 5px;
}

.market-builder-panel.staging-sell-builder .market-builder-controls label {
  gap: 3px;
}

.market-builder-panel.staging-sell-builder .market-builder-controls select {
  min-height: 28px;
}

.market-builder-panel.staging-sell-builder .market-amount-control {
  grid-template-columns: minmax(0, 1fr) 72px minmax(126px, 0.8fr);
}

.market-builder-panel.staging-sell-builder .market-amount-control strong {
  min-height: 30px;
}

.market-builder-panel.staging-sell-builder .market-builder-summary div {
  padding: 7px 8px;
}

.market-builder-panel.staging-sell-builder .market-builder-summary {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.market-builder-panel.staging-sell-builder .market-builder-actions {
  gap: 6px;
}

.market-builder-panel.staging-sell-builder .market-builder-actions button {
  min-height: 42px;
  font-size: 0.82rem;
}

@media (max-width: 980px) {
  .trade-terminal-summary,
  .map-one-market-terminal {
    grid-template-columns: 1fr;
    height: auto;
  }

  .market-builder-stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  .market-amount-control,
  .market-builder-stats,
  .market-builder-actions {
    grid-template-columns: 1fr;
  }
}

/* ===== Trade Terminal environment treatment ===== */
#marketScreen.market-screen {
  isolation: isolate;
  background-color: #020814;
  background-image:
    radial-gradient(ellipse at 50% 54%, rgba(1, 8, 18, 0.3), rgba(1, 8, 18, 0.1) 56%, rgba(1, 8, 18, 0.02) 82%),
    linear-gradient(180deg, rgba(1, 8, 18, 0.18), rgba(1, 8, 18, 0.38)),
    url("./assets/backgrounds/trade-terminal-trading-hub.png") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
}

#marketScreen::before,
#marketScreen::after {
  content: none;
}

#marketScreen > * {
  position: relative;
  z-index: 1;
}

#marketScreen .market-header {
  text-shadow: 0 0 18px rgba(0, 0, 0, 0.92);
}

#marketScreen .market-terminal {
  border: 1px solid rgba(110, 220, 255, 0.16);
  border-radius: 10px;
  padding: 12px;
  background: linear-gradient(180deg, rgba(0, 6, 16, 0.1), rgba(0, 6, 16, 0.22));
  box-shadow: inset 0 1px 0 rgba(158, 230, 255, 0.05), 0 18px 42px rgba(0, 0, 0, 0.24);
}

#marketScreen .terminal-card,
#marketScreen .market-board-panel,
#marketScreen .market-builder-panel {
  background:
    linear-gradient(90deg, rgba(70, 205, 255, 0.08), transparent 18%, transparent 82%, rgba(70, 205, 255, 0.05)),
    linear-gradient(180deg, rgba(4, 13, 26, 0.78), rgba(1, 7, 17, 0.84));
  border-color: rgba(115, 221, 255, 0.34);
  box-shadow:
    inset 0 1px 0 rgba(180, 238, 255, 0.07),
    0 10px 26px rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(2px);
}

/* ===== Trade Terminal V2: Daily Contracts + Live Market ===== */
#marketScreen.trade-terminal-screen-v2 {
  padding: 20px 24px 18px;
  color: #eaf7ff;
}

#marketScreen .trade-terminal-header-v2 {
  min-height: 92px;
  margin-bottom: 10px;
  align-items: flex-start;
}

#marketScreen .trade-terminal-header-v2 p {
  margin-bottom: 4px;
  color: #28dbf4;
  font-size: 0.82rem;
  letter-spacing: 0.13em;
}

#marketScreen .trade-terminal-header-v2 h2 {
  font-size: clamp(2.15rem, 3.2vw, 3.45rem);
  line-height: 0.98;
}

.trade-terminal-station-copy {
  display: block;
  max-width: 540px;
  margin-top: 10px;
  color: #c6d3df;
  font-size: 0.88rem;
  line-height: 1.35;
}

#marketScreen .trade-terminal-layout-v2 {
  display: block;
  height: calc(100% - 102px);
  min-height: 0;
  padding: 0;
  border: 0;
  background: none;
  box-shadow: none;
}

.trade-terminal-body-v2,
.trade-v2-view {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
}

.trade-v2-view {
  display: grid;
  grid-template-rows: 76px minmax(0, 1fr) 18px;
  gap: 10px;
}

.trade-v2-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  min-width: 0;
  border: 1px solid rgba(74, 196, 245, 0.36);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(3, 17, 31, 0.94), rgba(2, 10, 21, 0.95));
  box-shadow: inset 0 1px 0 rgba(170, 235, 255, 0.07), 0 10px 28px rgba(0, 0, 0, 0.2);
  overflow: hidden;
}

.trade-v2-summary-item {
  display: grid;
  grid-template-columns: 43px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 10px 14px;
  border-right: 1px solid rgba(90, 190, 255, 0.22);
}

.trade-v2-summary-item:last-child {
  border-right: 0;
}

.trade-v2-summary-icon,
.trade-v2-panel-icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid rgba(40, 211, 255, 0.62);
  border-radius: 9px;
  color: #2bd9ff;
  background: rgba(5, 39, 62, 0.64);
  font-size: 0.9rem;
  font-style: normal;
  font-weight: 950;
  box-shadow: inset 0 0 18px rgba(38, 198, 255, 0.08);
}

.trade-v2-summary-item > div,
.trade-v2-summary-copy {
  min-width: 0;
}

.trade-v2-summary-item span:not(.trade-v2-summary-icon) {
  display: block;
  margin-bottom: 3px;
  color: #29d7ef;
  font-size: 0.61rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.trade-v2-summary-item strong {
  display: block;
  color: #f2f7fb;
  font-size: clamp(0.82rem, 1.3vw, 1.07rem);
  line-height: 1.05;
  white-space: nowrap;
}

.trade-v2-summary-copy > i {
  display: block;
  width: min(130px, 100%);
  height: 5px;
  margin-top: 6px;
  border-radius: 999px;
  background: rgba(80, 130, 160, 0.22);
  overflow: hidden;
}

.trade-v2-summary-copy > i > b {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #1ecbdf, #32eaff);
}

.trade-v2-mini-dots,
.trade-v2-progress-line > span {
  display: flex !important;
  gap: 8px;
  margin-top: 6px;
}

.trade-v2-mini-dots i,
.trade-v2-progress-line i {
  display: block;
  width: 8px;
  height: 8px;
  border: 1px solid rgba(117, 244, 57, 0.44);
  border-radius: 50%;
  background: rgba(21, 66, 19, 0.34);
}

.trade-v2-mini-dots i.is-complete,
.trade-v2-progress-line i.is-complete {
  background: #75f439;
  box-shadow: 0 0 8px rgba(117, 244, 57, 0.54);
}

.trade-v2-primary-grid {
  display: grid;
  grid-template-columns: minmax(360px, 0.82fr) minmax(560px, 1.18fr);
  gap: 14px;
  min-width: 0;
  min-height: 0;
}

.trade-v2-primary-panel,
.trade-v2-contract-list,
.trade-v2-contract-detail,
.trade-v2-market-board,
.trade-v2-transaction {
  min-width: 0;
  min-height: 0;
  border: 1px solid rgba(69, 195, 244, 0.42);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba(2, 15, 29, 0.96), rgba(1, 8, 18, 0.97));
  box-shadow: inset 0 1px 0 rgba(169, 234, 255, 0.06), 0 12px 30px rgba(0, 0, 0, 0.22);
}

.trade-v2-primary-panel {
  display: grid;
  gap: 9px;
  padding: 14px;
  overflow: hidden;
}

.trade-v2-contracts-overview {
  grid-template-rows: auto auto minmax(0, 1fr) 48px;
  border-color: rgba(105, 225, 52, 0.62);
  background:
    radial-gradient(circle at 12% 12%, rgba(89, 221, 39, 0.1), transparent 34%),
