}

.trade-v2-market-table thead th {
  color: #27d6f3;
  font-size: 0.62rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.trade-v2-market-table thead th:first-child,
.trade-v2-market-table tbody th {
  width: 32%;
  text-align: left;
}

.trade-v2-market-table tbody th,
.trade-v2-market-table tbody td {
  color: #edf6ff;
  font-size: 0.76rem;
}

.trade-v2-market-table .is-current {
  background: rgba(29, 180, 229, 0.1);
  box-shadow: inset 0 -2px 0 rgba(41, 216, 243, 0.52);
}

.trade-v2-market-table tr[role="button"] {
  cursor: pointer;
}

.trade-v2-market-table tr[role="button"]:hover,
.trade-v2-market-table tr.is-selected {
  background: rgba(24, 134, 205, 0.14);
}

.trade-v2-market-table tr.is-selected th {
  box-shadow: inset 4px 0 0 #28d8f3;
}

.trade-v2-commodity {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.trade-v2-commodity img {
  width: 30px;
  height: 30px;
  object-fit: contain;
}

.trade-v2-trend {
  display: inline-block;
  margin-left: 6px;
  font-size: 0.68rem;
}

.trade-v2-trend.is-up { color: #73ef3d; }
.trade-v2-trend.is-down { color: #ff5d51; }
.trade-v2-trend.is-stable { color: #98b2c7; }

.trade-v2-tutorial-price {
  width: 100%;
  min-height: 32px;
  padding: 0;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.trade-v2-tutorial-price:hover,
.trade-v2-tutorial-price:focus-visible {
  background: rgba(41, 216, 243, 0.12);
  outline: 1px solid rgba(145, 236, 255, 0.8);
  outline-offset: 1px;
}

.trade-v2-market-note,
.trade-v2-contract-guidance,
.trade-v2-transaction-note,
.trade-v2-reserved-note {
  margin: 0;
  color: #a8c6df;
  font-size: 0.67rem;
  line-height: 1.32;
}

.trade-v2-market-note {
  padding: 7px 9px;
  border: 1px solid rgba(58, 177, 228, 0.24);
  border-radius: 6px;
  background: rgba(3, 19, 34, 0.62);
}

.trade-v2-market-note > span {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  margin-right: 8px;
  border: 1px solid #52d9f4;
  border-radius: 50%;
  color: #52d9f4;
  font-weight: 900;
}

.trade-v2-status {
  min-height: 18px;
  color: #89dff0;
  font-size: 0.65rem;
  text-align: center;
}

.trade-v2-dedicated {
  grid-template-rows: 76px 42px minmax(0, 1fr) 18px;
}

.trade-v2-dedicated-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  min-width: 0;
  padding: 6px 12px;
  border-bottom: 1px solid rgba(70, 191, 238, 0.28);
}

.trade-v2-dedicated-heading span {
  color: #2bd9f5;
  font-size: 0.62rem;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.trade-v2-dedicated-heading h3 {
  display: inline;
  margin-left: 10px;
  font-size: 0.94rem;
}

.trade-v2-dedicated-heading > strong {
  color: #b9d5e9;
  font-size: 0.67rem;
  text-transform: uppercase;
  white-space: nowrap;
}

.trade-v2-contracts-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(360px, 1.05fr);
  gap: 12px;
  min-height: 0;
}

.trade-v2-contract-list {
  display: grid;
  grid-template-rows: repeat(4, minmax(0, 1fr));
  gap: 7px;
  padding: 10px;
  overflow: hidden;
  border-color: rgba(109, 228, 60, 0.4);
}

.trade-v2-contract-card {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto 90px;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid rgba(83, 184, 223, 0.22);
  border-radius: 7px;
  color: #edf8ff;
  background: rgba(3, 16, 29, 0.76);
  font-family: inherit;
  text-align: left;
  cursor: pointer;
}

.trade-v2-contract-card:hover,
.trade-v2-contract-card.is-selected {
  border-color: rgba(105, 228, 59, 0.72);
  background: rgba(21, 66, 30, 0.36);
}

.trade-v2-contract-card.is-complete {
  opacity: 0.62;
}

.trade-v2-contract-card img {
  width: 36px;
  height: 36px;
  object-fit: contain;
}

.trade-v2-contract-card > div {
  min-width: 0;
}

.trade-v2-contract-card > div strong,
.trade-v2-contract-card > div span,
.trade-v2-contract-card > div small {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.trade-v2-contract-card > div strong { font-size: 0.8rem; }
.trade-v2-contract-card > div span { margin-top: 2px; color: #a9c6d8; font-size: 0.64rem; }
.trade-v2-contract-card > div small { margin-top: 3px; color: #6fcbe3; font-size: 0.57rem; }
.trade-v2-contract-card > b { justify-self: end; color: #78ef42; font-size: 0.78rem; white-space: nowrap; }

.trade-v2-contract-detail {
  display: grid;
  grid-template-rows: auto auto minmax(36px, 1fr) 48px;
  gap: 12px;
  padding: 14px;
}

.trade-v2-contract-detail > header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.trade-v2-contract-detail > header img {
  width: 58px;
  height: 58px;
  object-fit: contain;
}

.trade-v2-contract-detail h3 {
  margin: 5px 0 2px;
  font-size: 1.26rem;
}

.trade-v2-contract-detail header p {
  margin: 0;
  color: #adc4d7;
  font-size: 0.72rem;
}

.trade-v2-detail-grid,
.trade-v2-cargo-ledgers {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
}

.trade-v2-detail-grid > div,
.trade-v2-cargo-ledgers > div {
  min-width: 0;
  padding: 8px 9px;
  border: 1px solid rgba(78, 182, 225, 0.2);
  border-radius: 6px;
  background: rgba(3, 18, 32, 0.66);
}

.trade-v2-detail-grid span,
.trade-v2-cargo-ledgers span,
.trade-v2-total span,
.trade-v2-quantity > div:first-child span {
  display: block;
  margin-bottom: 3px;
  color: #6dd7ed;
  font-size: 0.55rem;
  font-weight: 900;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.trade-v2-detail-grid strong,
.trade-v2-cargo-ledgers strong {
  display: block;
  overflow: hidden;
  color: #f0f7fc;
  font-size: 0.72rem;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.trade-v2-contract-action:disabled,
.trade-v2-transaction-action:disabled {
  cursor: not-allowed;
  opacity: 0.48;
  filter: saturate(0.5);
}

.trade-v2-contract-action.is-complete {
  border-color: rgba(100, 235, 80, 0.5);
  background: linear-gradient(180deg, #246e36, #164623);
}

.trade-v2-market-grid {
  display: grid;
  grid-template-columns: minmax(520px, 1.24fr) minmax(330px, 0.76fr);
  gap: 12px;
  min-height: 0;
}

.trade-v2-market-board {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 8px;
  padding: 10px;
}

.trade-v2-transaction {
  display: grid;
  grid-template-rows: 36px auto auto auto auto 52px minmax(28px, 1fr);
  gap: 9px;
  padding: 11px;
  overflow: hidden;
}

.trade-v2-mode-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.trade-v2-mode-tabs button {
  border: 1px solid rgba(67, 188, 235, 0.3);
  border-radius: 5px;
  color: #9fc2d8;
  background: rgba(4, 18, 31, 0.76);
  font-family: inherit;
  font-size: 0.7rem;
  font-weight: 900;
  text-transform: uppercase;
  cursor: pointer;
}

.trade-v2-mode-tabs button.is-active {
  color: #fff;
  border-color: #34d8f4;
  background: linear-gradient(180deg, #1763b8, #0b3c82);
}

.trade-v2-transaction > header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.trade-v2-transaction > header img {
  width: 52px;
  height: 52px;
  object-fit: contain;
}

.trade-v2-transaction > header span {
  color: #69d5ec;
  font-size: 0.6rem;
  text-transform: uppercase;
}

.trade-v2-transaction > header h3 {
  margin: 2px 0;
  font-size: 1.15rem;
}

.trade-v2-transaction > header p {
  margin: 0;
  color: #aec8da;
  font-size: 0.68rem;
}

.trade-v2-quantity {
  display: grid;
  gap: 6px;
}

.trade-v2-quantity > div:first-child {
  display: flex;
  justify-content: space-between;
  align-items: end;
}

.trade-v2-quantity small {
  color: #99b5c8;
  font-size: 0.6rem;
}

.trade-v2-stepper {
  display: grid;
  grid-template-columns: 36px minmax(56px, 1fr) 36px 62px;
  gap: 6px;
}

.trade-v2-stepper button,
.trade-v2-stepper input {
  min-width: 0;
  min-height: 34px;
  border: 1px solid rgba(79, 191, 235, 0.32);
  border-radius: 5px;
  color: #eff9ff;
  background: rgba(3, 16, 29, 0.88);
  font-family: inherit;
  font-weight: 900;
  text-align: center;
}

.trade-v2-stepper button {
  cursor: pointer;
}

.trade-v2-stepper button:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}

.trade-v2-stepper .trade-v2-max {
  color: #71ed41;
  border-color: rgba(105, 234, 62, 0.4);
}

.trade-v2-total {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 9px 11px;
  border: 1px solid rgba(60, 195, 241, 0.28);
  border-radius: 6px;
  background: rgba(4, 29, 49, 0.62);
}

.trade-v2-total span {
  margin: 0;
}

.trade-v2-total strong {
  color: #fff;
  font-size: 1rem;
}

.trade-v2-transaction-note {
  align-self: start;
}

.trade-v2-reserved-note {
  color: #ffd05b;
}

@media (max-width: 1120px) {
  .trade-v2-summary-item {
    grid-template-columns: 34px minmax(0, 1fr);
    gap: 7px;
    padding: 8px 9px;
  }

  .trade-v2-summary-icon {
    width: 32px;
    height: 32px;
    font-size: 0.72rem;
  }

  .trade-v2-primary-grid {
    grid-template-columns: minmax(330px, 0.78fr) minmax(500px, 1.22fr);
  }

  .trade-v2-contract-preview {
    grid-template-columns: 24px 28px minmax(0, 1fr) 76px;
  }

  .trade-v2-contract-preview > em {
    display: none;
  }

  .trade-v2-market-grid {
    grid-template-columns: minmax(470px, 1.18fr) minmax(300px, 0.82fr);
  }
}

@media (max-width: 900px) {
  #marketScreen.trade-terminal-screen-v2 {
    overflow-y: auto;
  }

  #marketScreen .trade-terminal-layout-v2,
  .trade-terminal-body-v2,
  .trade-v2-view {
    height: auto;
    min-height: 100%;
  }

  .trade-v2-view,
  .trade-v2-dedicated {
    grid-template-rows: auto auto auto auto;
  }

  .trade-v2-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .trade-v2-summary-item:nth-child(2) {
    border-right: 0;
  }

  .trade-v2-primary-grid,
  .trade-v2-contracts-grid,
  .trade-v2-market-grid {
    grid-template-columns: 1fr;
  }

  .trade-v2-primary-panel,
  .trade-v2-contract-list,
  .trade-v2-contract-detail,
  .trade-v2-market-board,
  .trade-v2-transaction {
    min-height: 420px;
  }
}

