  }

  #tutorialCinematicContinue {
    min-height: 44px;
    margin-top: 16px;
  }

  .tutorial-cinematic__caption {
    display: none;
  }

  @keyframes tutorial-cinematic-copy-in {
    from { opacity: 0; transform: translateY(18px); }
    to { opacity: 1; transform: none; }
  }
}

@media (prefers-reduced-motion: reduce) {
  .tutorial-cinematic__image,
  .tutorial-cinematic__copy,
  .tutorial-cinematic__signal i {
    animation: none !important;
  }
