  object-fit: contain;
  filter: drop-shadow(0 0 10px rgba(127, 223, 255, 0.30));
}

.game-reward-kicker {
  color: #7fdfff;
  text-transform: uppercase;
  letter-spacing: 1.7px;
  font-size: 10px;
  font-weight: 1000;
  margin-bottom: 4px;
}

.game-reward-title {
  color: #f7fbff;
  font-size: 20px;
  font-weight: 1000;
  line-height: 1.05;
}

.game-reward-meta {
  margin-top: 6px;
  color: rgba(215, 235, 248, 0.78);
  font-size: 12px;
  font-weight: 800;
}

.game-reward-burst.bounty .game-reward-card {
  border-color: rgba(255, 210, 84, 0.68);
  box-shadow:
    0 0 0 2px rgba(255, 210, 84, 0.08),
