.quality-fx-host {
  --q: #45c8ff;
  --q2: #1d6dff;
}

.quality-fx-host.quality-fx--refined { --q: #2fff94; --q2: #12bc70; }
.quality-fx-host.quality-fx--advanced { --q: #38d9ff; --q2: #5373ff; }
.quality-fx-host.quality-fx--elite { --q: #be61ff; --q2: #ff4dd7; }
.quality-fx-host.quality-fx--legendary { --q: #ffd04b; --q2: #ff7b1f; }
.quality-fx-host.quality-fx--godlike { --q: #6dfff8; --q2: #ff2ccf; }

.upgrade-forge-screen .forge-chamber-visual.quality-fx-host::after {
  content: "";
  position: absolute;
  inset: 8% 20%;
  z-index: 2;
  pointer-events: none;
  border-radius: 50%;
  opacity: 0.32;
  background:
    conic-gradient(from 0deg, transparent, color-mix(in srgb, var(--q) 34%, transparent), transparent, color-mix(in srgb, var(--q2) 28%, transparent), transparent);
  filter: blur(14px);
  animation: qualityFxStorm 5.8s linear infinite;
}

.upgrade-forge-screen .forge-chamber-visual.quality-fx--elite::after,
.upgrade-forge-screen .forge-chamber-visual.quality-fx--legendary::after,
.upgrade-forge-screen .forge-chamber-visual.quality-fx--godlike::after {
  opacity: 0.56;
}

@keyframes qualityFxSweep {
  0% { transform: translateX(-135%) skewX(-18deg); }
  48%, 100% { transform: translateX(135%) skewX(-18deg); }
}

@keyframes qualityFxDrift {
  from { background-position: 0 0, 10px 8px; }
  to { background-position: 54px -54px, -12px 66px; }
}

@keyframes qualityFxBreathe {
  0%, 100% { transform: scale(0.88); opacity: calc(var(--fx-aura) * 0.72); }
  50% { transform: scale(1.14); opacity: var(--fx-aura); }
}

@keyframes qualityFxStorm {
  from { transform: rotate(0deg) scale(0.92); }
  50% { transform: rotate(180deg) scale(1.07); }
  to { transform: rotate(360deg) scale(0.92); }
}

@keyframes qualityFxOrbit1 {
  0%, 100% { transform: translate(-50%, -50%) rotate(-8deg) scale(0.96); }
  50% { transform: translate(-50%, -50%) rotate(-2deg) scale(1.08); }
}

@keyframes qualityFxOrbit2 {
  0%, 100% { transform: translate(-50%, -50%) rotate(9deg) scale(0.96); }
  50% { transform: translate(-50%, -50%) rotate(16deg) scale(1.09); }
}

@keyframes qualityFxOrbit3 {
  0%, 100% { transform: translate(-50%, -50%) rotate(23deg) scale(0.94); }
  50% { transform: translate(-50%, -50%) rotate(35deg) scale(1.12); }
}

@keyframes qualityFxBolt {
  0%, 54%, 100% { opacity: 0; }
  56% { opacity: calc(var(--fx-bolt) * 0.14); }
  57% { opacity: var(--fx-bolt); }
  59% { opacity: calc(var(--fx-bolt) * 0.1); }
  60% { opacity: calc(var(--fx-bolt) * 0.86); }
  62% { opacity: calc(var(--fx-bolt) * 0.06); }
  64% { opacity: calc(var(--fx-bolt) * 0.72); }
  66% { opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .quality-fx,
  .quality-fx *,
  .quality-fx::before,
  .quality-fx::after,
  .quality-fx-host::after {
    animation: none !important;
  }

  .quality-fx__bolt {
    opacity: 0 !important;
  }

  .quality-fx__storm {
    opacity: calc(var(--fx-storm) * 0.32) !important;
  }
}

