/* Mission Journal */

.mission-journal-panel {
  position: absolute;
  left: clamp(18px, 3vw, 42px);
  top: clamp(150px, 23vh, 210px);
  width: min(420px, 34vw);
  max-height: min(470px, 54vh);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 10px;
  color: #eaf7ff;
  z-index: 4;
}

.mission-journal-head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 14px;
  border: 1px solid rgba(127, 214, 255, 0.35);
  border-radius: 8px;
  background: rgba(5, 18, 28, 0.82);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.28);
}

.mission-journal-head span,
.mission-card-top span,
.morgan-card span,
.mission-reward-row span {
  display: block;
  color: #86c9e8;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mission-journal-head strong {
  display: block;
  margin-top: 2px;
  font-size: 1rem;
}

.mission-journal-head small {
  display: block;
  color: #b5c8d3;
  font-size: 0.78rem;
}

.mission-journal-head em {
  align-self: flex-start;
  min-width: 54px;
  padding: 5px 8px;
  border: 1px solid rgba(127, 214, 255, 0.26);
  border-radius: 999px;
  background: rgba(127, 214, 255, 0.1);
  color: #ffffff;
  font-style: normal;
  font-size: 0.74rem;
  text-align: center;
}

.mission-journal-list {
  display: grid;
  gap: 10px;
  overflow: auto;
  padding-right: 4px;
}

.mission-card {
  padding: 12px;
  border: 1px solid rgba(127, 214, 255, 0.22);
  border-radius: 8px;
  background: rgba(3, 12, 20, 0.82);
}

.mission-card.mission-state-locked {
  opacity: 0.62;
}

.mission-card-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.mission-card-top strong {
  font-size: 0.95rem;
  text-align: right;
}

.morgan-card {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 10px;
  margin: 10px 0;
  padding: 9px;
  border-radius: 7px;
  background: rgba(42, 104, 132, 0.18);
}

.morgan-avatar,
.mission-objective-icon,
.chapter-progress-mark {
  display: grid;
  place-items: center;
  border: 1px solid rgba(127, 214, 255, 0.38);
  background: rgba(127, 214, 255, 0.13);
  color: #ffffff;
  font-weight: 900;
}

.morgan-card-portrait {
  width: 42px;
  height: 42px;
  border-radius: 8px;
  object-fit: cover;
  border: 1px solid rgba(127, 214, 255, 0.38);
}

.morgan-avatar {
  width: 42px;
  height: 42px;
  border-radius: 8px;
}

.morgan-card p {
  margin: 3px 0 0;
  color: #d6e7ef;
  font-size: 0.8rem;
  line-height: 1.35;
}

.mission-objective-line,
.mission-lock-note {
  color: #b9cbd6;
  font-size: 0.78rem;
}

.mission-progress-row,
.mission-reward-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 9px;
}

.mission-progress-track {
  flex: 1;
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.11);
}

.mission-progress-track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #46e6a4, #7fd6ff);
}

.mission-progress-row b,
.mission-reward-row strong {
  color: #ffffff;
  font-size: 0.76rem;
}

.mission-actions {
  margin-top: 10px;
}

.mission-actions button {
  width: 100%;
  min-height: 34px;
  border: 1px solid rgba(127, 214, 255, 0.42);
  border-radius: 7px;
  background: rgba(64, 165, 214, 0.24);
  color: #ffffff;
  font-weight: 900;
  cursor: pointer;
}

.active-mission-summary {
  margin-top: 10px;
}

.mission-objective-card {
  border-color: rgba(70, 230, 164, 0.36);
}

.mission-objective-icon {
  width: 44px;
  height: 44px;
  border-radius: 8px;
  flex: 0 0 44px;
}

.mission-pill {
  background: rgba(70, 230, 164, 0.15);
  color: #9cffd0;
}

.mission-objective-empty {
  padding: 10px;
  border: 1px solid rgba(127, 214, 255, 0.15);
  border-radius: 7px;
  color: #9fb5c2;
  font-size: 0.82rem;
}

.chapter-progress-card {
  min-height: 190px;
}

.chapter-progress-panel {
  display: grid;
  grid-template-columns: 64px 1fr;
  gap: 14px;
  align-items: center;
}

.chapter-progress-mark {
  width: 64px;
  height: 64px;
  border-radius: 8px;
  font-size: 1.8rem;
}

.chapter-progress-panel strong,
.chapter-progress-panel em {
  display: block;
}

.chapter-progress-panel em {
  margin: 4px 0 8px;
  color: #b5c8d3;
  font-style: normal;
}

@media (max-width: 980px) {
  .mission-journal-panel {
    left: 16px;
    right: 16px;
    top: 118px;
    width: auto;
    max-height: 34vh;
  }
