  letter-spacing: 0.04em;
}

.journey-body {
  width: min(1180px, calc(100vw - 48px));
  height: min(610px, calc(100vh - 126px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.75fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 14px;
}

.journey-morgan-panel,
.journey-chapters-panel,
.journey-objectives-panel,
.journey-rewards-panel,
.journey-galaxy-panel {
  border: 1px solid rgba(127, 214, 255, 0.26);
  border-radius: 8px;
  background: rgba(4, 15, 25, 0.86);
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.28);
}

.journey-morgan-panel {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 96px 1fr;
  align-items: center;
  gap: 16px;
  min-height: 118px;
  padding: 14px 16px;
}

.journey-morgan-portrait {
  width: 92px;
  height: 92px;
  border-radius: 8px;
  object-fit: cover;
  border: 1px solid rgba(127, 214, 255, 0.55);
  box-shadow: 0 0 26px rgba(57, 199, 255, 0.18);
}

.journey-morgan-copy span,
.journey-panel-head span,
.journey-galaxy-panel span {
  display: block;
  color: #86dfff;
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.journey-morgan-copy strong {
  display: block;
  margin-top: 2px;
  color: #ffffff;
  font-size: 1.18rem;
  letter-spacing: 0.08em;
}

.journey-morgan-copy p {
  max-width: 740px;
  margin: 7px 0 8px;
  color: #d7e7ef;
  font-size: 0.92rem;
  line-height: 1.38;
}

.journey-waveform {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 14px;
}

.journey-waveform i {
  display: block;
  width: 34px;
  height: 2px;
  border-radius: 999px;
  background: rgba(127, 214, 255, 0.42);
}

.journey-waveform i:nth-child(2),
.journey-waveform i:nth-child(4) {
  width: 18px;
  background: rgba(70, 230, 164, 0.46);
}

.journey-chapters-panel {
  min-height: 0;
  padding: 14px;
  overflow: hidden;
}

.journey-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.journey-chapter-stack {
  display: grid;
  gap: 10px;
  max-height: 100%;
  overflow: auto;
  padding-right: 4px;
}

.journey-chapter-card {
  display: grid;
  grid-template-columns: 52px 1fr;
  gap: 12px;
  padding: 12px;
  border: 1px solid rgba(127, 214, 255, 0.18);
  border-radius: 8px;
  background: rgba(8, 25, 38, 0.72);
}

.journey-chapter-card.journey-chapter-active {
  border-color: rgba(92, 215, 255, 0.7);
  box-shadow: inset 0 0 0 1px rgba(92, 215, 255, 0.1), 0 0 24px rgba(57, 199, 255, 0.13);
}

.journey-chapter-card.journey-chapter-locked,
.journey-chapter-card.journey-chapter-soon {
  background: rgba(8, 18, 28, 0.58);
}

.journey-chapter-badge {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border: 1px solid rgba(127, 214, 255, 0.38);
  border-radius: 8px;
  background: rgba(127, 214, 255, 0.11);
  color: #ffffff;
  font-weight: 900;
}

.journey-chapter-title-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.journey-chapter-title-row strong {
  display: block;
  color: #ffffff;
  font-size: 0.98rem;
}

.journey-chapter-title-row p {
  margin: 3px 0 0;
  color: #b8cbd6;
  font-size: 0.82rem;
}

.journey-status-pill {
  align-self: flex-start;
  flex: 0 0 auto;
  padding: 5px 8px;
  border: 1px solid rgba(127, 214, 255, 0.26);
  border-radius: 999px;
  background: rgba(127, 214, 255, 0.1);
  color: #ffffff;
  font-size: 0.65rem;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.journey-chapter-progress {
  display: grid;
  grid-template-columns: 1fr 44px;
  align-items: center;
  gap: 10px;
  margin: 10px 0 6px;
}

.journey-progress-track,
.journey-galaxy-track {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
}

.journey-progress-track i,
.journey-galaxy-track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #46e6a4, #6bd7ff);
}

.journey-chapter-progress em,
.journey-chapter-main small {
  color: #c4d8e2;
  font-size: 0.78rem;
  font-style: normal;
}

.journey-side-panel {
  min-height: 0;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 14px;
}

.journey-objectives-panel,
.journey-rewards-panel {
  min-height: 0;
  padding: 14px;
}

.journey-objective-list {
  display: grid;
  gap: 9px;
  max-height: 300px;
  overflow: auto;
  padding-right: 4px;
}

.journey-objective-row {
  display: grid;
  grid-template-columns: 14px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border: 1px solid rgba(127, 214, 255, 0.17);
  border-radius: 8px;
  background: rgba(7, 23, 36, 0.72);
}

.journey-objective-row.mission-state-completed {
  border-color: rgba(70, 230, 164, 0.42);
}

.journey-objective-marker {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: #6bd7ff;
  box-shadow: 0 0 14px rgba(107, 215, 255, 0.5);
}

.journey-objective-copy strong,
.journey-reward-row strong {
  display: block;
  color: #ffffff;
  font-size: 0.84rem;
}

.journey-objective-copy span,
.journey-reward-row small,
.journey-empty-objectives span {
  display: block;
  margin: 2px 0 6px;
  color: #aebfca;
  font-size: 0.72rem;
}

.journey-objective-row b {
  color: #ffffff;
  font-size: 0.78rem;
  white-space: nowrap;
}

.journey-objective-action {
  grid-column: 2 / -1;
}

.journey-objective-action button {
  width: 100%;
  min-height: 32px;
  border: 1px solid rgba(127, 214, 255, 0.42);
  border-radius: 7px;
  background: rgba(64, 165, 214, 0.24);
  color: #ffffff;
  font-weight: 900;
  cursor: pointer;
}

.journey-empty-objectives {
  padding: 14px;
  border: 1px solid rgba(127, 214, 255, 0.16);
  border-radius: 8px;
  background: rgba(7, 23, 36, 0.56);
}

.journey-empty-objectives strong {
  display: block;
  color: #ffffff;
  margin-bottom: 4px;
}

.journey-reward-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.journey-reward-row {
  min-height: 72px;
  padding: 9px;
  border: 1px solid rgba(127, 214, 255, 0.17);
  border-radius: 8px;
  background: rgba(7, 23, 36, 0.72);
}

.journey-reward-row > span {
  display: inline-grid;
  place-items: center;
  min-width: 28px;
  height: 24px;
  margin-bottom: 7px;
  border-radius: 6px;
  background: rgba(127, 214, 255, 0.13);
  color: #8ce4ff;
  font-size: 0.64rem;
  font-weight: 900;
}

.journey-galaxy-panel {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr) 360px;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
}

.journey-galaxy-panel strong {
  display: block;
  margin-top: 2px;
  color: #ffffff;
  font-size: 1.2rem;
}

.journey-galaxy-panel p {
  margin: 0;
  color: #b8cbd6;
  font-size: 0.82rem;
  line-height: 1.3;
}

@media (max-width: 980px) {
  .journey-body {
    width: calc(100vw - 28px);
    height: auto;
    max-height: calc(100vh - 116px);
    overflow: auto;
    grid-template-columns: 1fr;
    grid-template-rows: none;
  }

  .journey-morgan-panel,
  .journey-galaxy-panel {
    grid-column: auto;
  }

  .journey-galaxy-panel {
    grid-template-columns: 1fr;
  }

  .journey-reward-list {
    grid-template-columns: 1fr;
  }
}

/* Morgan Command Liaison Journey briefing upgrade. */
.journey-briefing {
  position: relative;
  min-height: 132px;
  display: grid;
  grid-template-columns: 124px minmax(0, 1fr);
  align-items: center;
  gap: 18px;
  padding: 14px 20px;
  overflow: hidden;
  border-color: rgba(95, 218, 255, 0.46);
  background:
    linear-gradient(90deg, rgba(3, 12, 22, 0.96), rgba(4, 18, 31, 0.92) 42%, rgba(4, 18, 31, 0.55)),
    rgba(4, 15, 25, 0.9);
  box-shadow: 0 20px 46px rgba(0, 0, 0, 0.32), inset 0 0 30px rgba(95, 218, 255, 0.07);
}

.journey-briefing::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(90deg, rgba(3, 12, 22, 0.92) 0%, rgba(3, 12, 22, 0.8) 36%, rgba(3, 12, 22, 0.24) 64%, rgba(3, 12, 22, 0.1) 100%),
    radial-gradient(circle at 22% 50%, rgba(95, 218, 255, 0.12), transparent 34%);
  pointer-events: none;
}

.journey-briefing::after {
  content: "";
  position: absolute;
  inset: 16px auto 16px 160px;
  z-index: 2;
  width: 1px;
  background: linear-gradient(180deg, transparent, rgba(95, 218, 255, 0.5), transparent);
}

.journey-briefing__bg {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 0;
  width: 58%;
  min-height: 132px;
  background-image: url("assets/journey-morgan-bg.png");
  background-repeat: no-repeat;
  background-position: right center;
  background-size: cover;
  opacity: 0.62;
}

.journey-briefing__portrait,
.journey-briefing__content {
  position: relative;
  z-index: 3;
}

.journey-briefing__portrait {
  width: 116px;
  height: 104px;
  display: grid;
  place-items: center;
  padding: 5px;
  border: 1px solid rgba(95, 218, 255, 0.58);
  border-radius: 8px;
  background: rgba(1, 12, 22, 0.62);
  box-shadow: 0 0 22px rgba(55, 196, 255, 0.2), inset 0 0 18px rgba(95, 218, 255, 0.08);
}

.journey-briefing__portrait-img,
.journey-morgan-portrait.journey-briefing__portrait-img {
  width: 100%;
  height: 100%;
  border: 0;
  border-radius: 6px;
  object-fit: cover;
  object-position: center 34%;
  box-shadow: none;
}

.journey-briefing__content {
  min-width: 0;
  max-width: 650px;
  padding-left: 4px;
}

.journey-briefing__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #86dfff;
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.journey-briefing__eyebrow i {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: #58d8ff;
  box-shadow: 0 0 13px rgba(88, 216, 255, 0.82);
}

.journey-briefing__name {
  display: block;
  margin-top: 5px;
  color: #4fd7ff;
  font-size: 1.34rem;
  font-weight: 900;
  letter-spacing: 0.16em;
  line-height: 1;
  text-shadow: 0 0 18px rgba(79, 215, 255, 0.28);
}

.journey-briefing__role {
  display: block;
  margin-top: 5px;
  color: #e7f5fb;
  font-size: 0.76rem;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.16em;
}

.journey-briefing__message {
  max-width: 600px;
  margin: 9px 0 8px;
  color: #dceef6;
  font-size: 0.9rem;
  line-height: 1.35;
}

.journey-briefing__waveform {
  height: 9px;
  opacity: 0.72;
}

.journey-briefing__waveform i {
  width: 34px;
  height: 2px;
  background: rgba(95, 218, 255, 0.54);
}

@media (max-width: 980px) {
  .journey-briefing {
    min-height: 118px;
    grid-template-columns: 96px minmax(0, 1fr);
    gap: 13px;
    padding: 12px 14px;
  }

  .journey-briefing::after {
    display: none;
  }

  .journey-briefing__bg {
    width: 70%;
    min-height: 118px;
    opacity: 0.32;
  }

  .journey-briefing__portrait {
    width: 92px;
    height: 92px;
  }

  .journey-briefing__name {
    font-size: 1.08rem;
  }

  .journey-briefing__message {
    font-size: 0.82rem;
  }
}

/* Config-driven Journey progression UI. Keep this block last in the Journey cascade. */
.journey-body {
  width: 100%;
  max-width: 1180px;
  box-sizing: border-box;
  height: min(598px, calc(100vh - 150px));
  grid-template-columns: minmax(0, 1fr) minmax(252px, 292px);
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  gap: 13px;
}

.journey-briefing,
.journey-chapters-panel,
.journey-current-path,
.journey-frontier-status,
.journey-galaxy-strip {
  border: 1px solid rgba(127, 214, 255, 0.25);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(8, 24, 39, 0.94), rgba(3, 13, 23, 0.9)),
    rgba(4, 15, 25, 0.86);
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.28);
}

.journey-briefing {
  position: relative;
  min-height: 94px;
  grid-template-columns: 78px minmax(0, 1fr);
  gap: 15px;
  padding: 12px 16px;
  overflow: hidden;
}

.journey-briefing::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 10% 18%, rgba(107, 215, 255, 0.12), transparent 36%),
    linear-gradient(90deg, rgba(107, 215, 255, 0.05), transparent 38%);
  pointer-events: none;
}

.journey-briefing::after {
  content: "";
  position: absolute;
  inset: 12px auto 12px 104px;
  width: 1px;
  background: linear-gradient(180deg, transparent, rgba(127, 214, 255, 0.38), transparent);
}

.journey-briefing > * {
  position: relative;
  z-index: 1;
}

.journey-morgan-portrait {
  width: 74px;
  height: 74px;
  border-radius: 8px;
  border-color: rgba(127, 214, 255, 0.62);
  box-shadow: 0 0 24px rgba(57, 199, 255, 0.2), 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.journey-morgan-copy {
  min-width: 0;
  padding-left: 6px;
}

.journey-morgan-copy p {
  max-width: 760px;
  margin: 6px 0 6px;
  color: #dceef6;
  font-size: 0.88rem;
}

.journey-chapters-panel {
  grid-column: 1 / -1;
  padding: 12px 14px;
  overflow: hidden;
}

.journey-chapter-path {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.42fr) minmax(0, 0.86fr);
  gap: 14px;
}

.journey-chapter-path::before {
  content: "";
  position: absolute;
  left: 13%;
  right: 13%;
  top: 34px;
  height: 2px;
  background: linear-gradient(90deg, rgba(155, 178, 194, 0.2), rgba(107, 215, 255, 0.75) 48%, rgba(147, 122, 255, 0.28));
  box-shadow: 0 0 14px rgba(86, 215, 255, 0.14);
  pointer-events: none;
}

.journey-chapter-node {
  position: relative;
  z-index: 1;
  min-height: 96px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid rgba(127, 214, 255, 0.18);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(8, 28, 43, 0.88), rgba(5, 16, 27, 0.86));
}

.journey-chapter-node::before {
  content: "";
  position: absolute;
  top: 29px;
  left: 31px;
  width: 12px;
  height: 12px;
  border-radius: 999px;
  background: #6bd7ff;
  box-shadow: 0 0 16px rgba(107, 215, 255, 0.55);
}

.journey-chapter-node--active {
  min-height: 112px;
  border-color: rgba(107, 215, 255, 0.92);
  background:
    radial-gradient(circle at 22% 16%, rgba(107, 215, 255, 0.26), transparent 48%),
    linear-gradient(180deg, rgba(13, 54, 82, 0.94), rgba(3, 18, 32, 0.94));
  box-shadow: 0 0 24px rgba(57, 199, 255, 0.16), inset 0 0 26px rgba(107, 215, 255, 0.08);
}

.journey-chapter-node--pending {
  opacity: 0.76;
}

.journey-chapter-node--locked {
  opacity: 0.82;
  border-color: rgba(147, 122, 255, 0.24);
  background:
    radial-gradient(circle at 78% 18%, rgba(135, 104, 255, 0.16), transparent 48%),
    linear-gradient(180deg, rgba(13, 18, 35, 0.78), rgba(5, 12, 24, 0.84));
}

.journey-chapter-icon {
  width: 38px;
  height: 38px;
}

.journey-current-path {
  grid-column: 1;
  grid-row: 3 / 5;
  padding: 16px;
  overflow: hidden;
  border-color: rgba(107, 215, 255, 0.34);
  box-shadow: 0 18px 44px rgba(0, 0, 0, 0.3), inset 0 0 26px rgba(107, 215, 255, 0.04);
}

.journey-assignment-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  max-height: calc(100% - 44px);
  overflow: auto;
  padding-right: 6px;
}

.journey-assignment-card {
  position: relative;
  min-height: 160px;
  grid-template-columns: 10px minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr) auto;
  align-items: stretch;
  gap: 11px;
  padding: 13px;
  border-color: color-mix(in srgb, var(--journey-accent, #6bd7ff) 38%, rgba(127, 214, 255, 0.14));
  background:
    linear-gradient(180deg, rgba(8, 25, 39, 0.92), rgba(5, 17, 29, 0.9)),
    radial-gradient(circle at 8% 0%, color-mix(in srgb, var(--journey-accent, #6bd7ff) 20%, transparent), transparent 40%);
}

.journey-assignment-card::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.journey-assignment-card--cyan {
  --journey-accent: #6bd7ff;
}

.journey-assignment-card--gold {
  --journey-accent: #f5c85c;
}

.journey-assignment-card--teal {
  --journey-accent: #46e6a4;
}

.journey-assignment-card--orange {
  --journey-accent: #ff8a5c;
}

.journey-assignment-card--purple {
  --journey-accent: #c79cff;
}

.journey-assignment-card.mission-state-claimable,
.journey-assignment-card.mission-state-completed {
  --journey-accent: #46e6a4;
  border-color: rgba(70, 230, 164, 0.86);
  background:
    linear-gradient(135deg, rgba(70, 230, 164, 0.16), rgba(7, 23, 36, 0.76) 42%),
    rgba(7, 23, 36, 0.72);
  box-shadow: inset 0 0 0 1px rgba(141, 255, 196, 0.08), 0 0 18px rgba(70, 230, 164, 0.18);
}

.journey-assignment-card.mission-state-claimed {
  --journey-accent: #46e6a4;
  border-color: rgba(70, 230, 164, 0.62);
}

.journey-assignment-card.mission-state-claimable .journey-objective-copy p,
.journey-assignment-card.mission-state-completed .journey-objective-copy p,
.journey-assignment-card.mission-state-claimed .journey-objective-copy p {
  color: rgba(211, 228, 236, 0.68);
}

.journey-assignment-card.mission-state-claimable .journey-progress-track i,
.journey-assignment-card.mission-state-completed .journey-progress-track i,
.journey-assignment-card.mission-state-claimed .journey-progress-track i {
  background: linear-gradient(90deg, #36f28f, #8dffc4);
  box-shadow: 0 0 10px rgba(70, 230, 164, 0.58);
}

.journey-assignment-card.mission-state-claimable .journey-status-pill--completed,
.journey-assignment-card.mission-state-completed .journey-status-pill--completed,
.journey-assignment-card.mission-state-claimed .journey-status-pill--completed {
  border-color: rgba(70, 230, 164, 0.74);
  background: rgba(70, 230, 164, 0.16);
  color: #a9ffd1;
  box-shadow: 0 0 12px rgba(70, 230, 164, 0.2);
}

.journey-assignment-card .journey-status-pill--completed::before,
.journey-assignment-card .journey-status-pill--claimed::before {
  content: "\2713";
  margin-right: 4px;
  color: #6dffad;
}

.journey-assignment-card.mission-state-completed {
  opacity: 0.64;
}

.journey-assignment-icon {
  width: 7px;
  height: 100%;
  border-radius: 999px;
  background: var(--journey-accent, #6bd7ff);
  box-shadow: 0 0 16px color-mix(in srgb, var(--journey-accent, #6bd7ff) 56%, transparent);
}

.journey-status-pill {
  border-color: rgba(127, 214, 255, 0.26);
  background: rgba(127, 214, 255, 0.1);
}

.journey-status-pill--active {
  border-color: rgba(107, 215, 255, 0.52);
  background: rgba(107, 215, 255, 0.15);
}

.journey-status-pill--available,
.journey-status-pill--pending {
  border-color: rgba(159, 177, 189, 0.28);
  background: rgba(159, 177, 189, 0.08);
