  gap: 15px;
  padding: 12px 16px;
  overflow: hidden;
}

.journey-briefing::after {
  content: "";
  position: absolute;
  inset: 12px auto 12px 104px;
  width: 1px;
  background: linear-gradient(180deg, transparent, rgba(127, 214, 255, 0.38), transparent);
}

.journey-morgan-portrait {
  width: 74px;
  height: 74px;
}

.journey-chapter-path {
  grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.42fr) minmax(0, 0.86fr);
  gap: 14px;
}

.journey-chapter-path::before {
  left: 13%;
  right: 13%;
  top: 34px;
  height: 2px;
  background: linear-gradient(90deg, rgba(155, 178, 194, 0.2), rgba(107, 215, 255, 0.75) 48%, rgba(147, 122, 255, 0.28));
