}

.journey-chapter-node--pending {
  opacity: 0.76;
}

.journey-chapter-node--locked {
  opacity: 0.82;
  border-color: rgba(147, 122, 255, 0.24);
}

.journey-chapter-route {
  grid-column: 1 / -1;
  min-height: 104px;
  padding: 9px 12px 10px;
  overflow: hidden;
}

.journey-chapter-route__head {
  margin-bottom: 7px;
}

.journey-chapter-route__track {
  position: relative;
  display: flex;
  align-items: center;
  gap: 46px;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 0 4px 3px;
  scroll-snap-type: x proximity;
