  background: rgba(49, 207, 255, 0.34);
}

.journey-chapter-route__item {
  position: relative;
  flex: 0 0 288px;
  min-height: 64px;
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  border: 1px solid rgba(107, 215, 255, 0.22);
  border-radius: 8px;
  background:
    radial-gradient(circle at 10% 50%, rgba(49, 207, 255, 0.12), transparent 44%),
