/* Semi-interactive Chapter Route carousel. */
.journey-chapter-route {
  position: relative;
  min-height: 82px;
  padding: 5px 14px 6px;
  background:
    linear-gradient(90deg, rgba(1, 10, 20, 0.92), rgba(7, 25, 40, 0.82) 50%, rgba(1, 10, 20, 0.92)),
    rgba(3, 13, 23, 0.9);
