  margin: 0;
  color: rgba(189, 215, 232, 0.72);
  font-size: 0.54rem;
  line-height: 1;
  text-align: center;
}

.journey-current-path {
  grid-column: 1;
  grid-row: 3;
  padding: 13px;
  overflow: hidden;
  border-color: rgba(107, 215, 255, 0.34);
}

.journey-assignment-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  max-height: calc(100% - 34px);
  overflow: auto;
  padding-right: 6px;
}

.journey-assignment-card {
  position: relative;
  min-height: 88px;
  grid-template-columns: 38px minmax(0, 1fr);
  grid-template-rows: auto;
  gap: 8px;
  padding: 8px 9px;
  border-color: color-mix(in srgb, var(--journey-accent, #6bd7ff) 38%, rgba(127, 214, 255, 0.14));
}

.journey-assignment-card.mission-state-in-progress {
  border-color: color-mix(in srgb, var(--journey-accent, #6bd7ff) 58%, rgba(127, 214, 255, 0.18));
}

.journey-assignment-card .journey-objective-copy {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.journey-assignment-card .journey-objective-top {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 8px;
}

.journey-assignment-card .journey-objective-top strong {
  min-width: 0;
  color: #ffffff;
  font-size: 0.76rem;
  line-height: 1.15;
}

.journey-assignment-card .journey-status-pill {
  flex: 0 0 auto;
  padding: 3px 6px;
  font-size: 0.53rem;
}

.journey-assignment-card .journey-objective-copy p {
  margin: 0;
  color: #d3e4ec;
  font-size: 0.66rem;
  line-height: 1.2;
}

.journey-assignment-progress-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 7px;
}

.journey-assignment-progress-row .journey-progress-track {
  height: 6px;
}

.journey-assignment-progress-row b {
  color: #ffffff;
  font-size: 0.72rem;
  white-space: nowrap;
}

.journey-assignment-progress-row .journey-reward-chips {
  justify-content: flex-end;
  flex-wrap: nowrap;
  gap: 5px;
}

.journey-assignment-card .journey-objective-action {
  grid-column: auto;
}

.journey-assignment-card .journey-objective-action button {
  min-height: 28px;
  width: 100%;
  font-size: 0.68rem;
}

.journey-assignment-card--cyan {
  --journey-accent: #6bd7ff;
}

.journey-assignment-card--gold {
  --journey-accent: #f5c85c;
}

.journey-assignment-card--teal {
  --journey-accent: #46e6a4;
}

.journey-assignment-card--orange {
  --journey-accent: #ff8a5c;
}

.journey-assignment-card--purple {
  --journey-accent: #c79cff;
}

.journey-assignment-card.mission-state-claimable,
.journey-assignment-card.mission-state-completed {
  --journey-accent: #46e6a4;
  border-color: rgba(70, 230, 164, 0.68);
}

.journey-assignment-icon {
  width: 36px;
  height: 36px;
  align-self: start;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: rgba(1, 9, 18, 0.36);
  box-shadow: 0 0 14px color-mix(in srgb, var(--journey-accent, #6bd7ff) 32%, transparent);
}

.journey-assignment-icon img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
}

.journey-reward-chip {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: 0.62rem;
  font-weight: 900;
}

.journey-reward-chip--xp {
  border: 1px solid rgba(107, 215, 255, 0.32);
  background: rgba(107, 215, 255, 0.1);
  color: #b7efff;
}

.journey-reward-chip--credits {
  border: 1px solid rgba(245, 200, 92, 0.32);
  background: rgba(245, 200, 92, 0.1);
  color: #ffe3a3;
}

.journey-frontier-status {
  height: 100%;
  min-height: 0;
  padding: 12px;
}

.journey-side-panel {
  grid-column: 2;
  grid-row: 3;
  min-height: 0;
}

.journey-frontier-status .journey-panel-head span {
  letter-spacing: 0.14em;
}

.journey-summary-compact {
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(127, 214, 255, 0.14);
  border-radius: 8px;
  background: rgba(7, 23, 36, 0.56);
}

.journey-summary-compact__metric,
.journey-summary-compact__requirements {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.journey-summary-compact span {
  color: #87dffb;
  font-size: 0.66rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.journey-summary-compact strong {
  color: #ffffff;
  font-size: 0.9rem;
}

.journey-summary-compact p {
  margin: 0;
  color: #b8cbd6;
  font-size: 0.72rem;
  line-height: 1.25;
}

.journey-galaxy-strip {
  grid-column: 1 / -1;
  grid-row: 4;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 28px;
  padding: 4px 12px;
  overflow: hidden;
  line-height: 1;
}

.journey-galaxy-strip span {
  white-space: nowrap;
  font-size: 0.66rem;
  letter-spacing: 0.1em;
}

.journey-galaxy-strip strong {
  white-space: nowrap;
  font-size: 0.78rem;
}

.journey-galaxy-strip .journey-progress-track {
  height: 5px;
}

@media (max-width: 980px) {
  .journey-body {
    width: 100%;
    height: auto;
    max-height: calc(100vh - 116px);
    overflow: auto;
    grid-template-columns: 1fr;
    grid-template-rows: none;
  }

  .journey-briefing::after {
    display: none;
  }

  .journey-chapter-path,
  .journey-assignment-grid {
    grid-template-columns: 1fr;
  }

  .journey-briefing,
  .journey-chapters-panel,
  .journey-current-path,
  .journey-side-panel,
  .journey-galaxy-strip {
    grid-column: auto;
    grid-row: auto;
  }

  .journey-galaxy-strip {
    grid-template-columns: 1fr;
  }
}

/* Journey usability and Oracle presentation refinement. */
.journey-briefing__inner {
