}

.journey-chapter-route__status {
  display: inline-flex;
  width: max-content;
  min-height: 16px;
  align-items: center;
  margin-top: 4px;
  padding: 2px 6px;
  border: 1px solid rgba(107, 215, 255, 0.2);
  border-radius: 999px;
  background: rgba(3, 16, 28, 0.68);
  font-size: 0.52rem;
  line-height: 1;
}

.journey-chapter-route__item--active .journey-chapter-route__status {
  border-color: rgba(94, 228, 255, 0.42);
