}

.journey-chapter-route__item--complete .journey-chapter-route__status {
  border-color: rgba(101, 245, 152, 0.4);
  background: rgba(78, 235, 137, 0.1);
}

.journey-chapter-route__item--locked .journey-chapter-route__status {
  border-color: rgba(185, 156, 255, 0.34);
