/* ===== Map 1 simple Lupen Forge ===== */
.upgrade-forge-screen {
  position: relative;
  overflow: hidden;
  min-height: 100vh;
  padding: 16px 18px 18px;
  background:
    linear-gradient(90deg, rgba(1, 8, 17, 0.94), rgba(0, 10, 22, 0.72)),
    url("assets/ui/forge/forge-chamber.png") center / cover no-repeat,
    #020810;
}

.upgrade-forge-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 52% 38%, rgba(46, 203, 255, 0.2), transparent 32%),
    linear-gradient(180deg, rgba(4, 22, 39, 0.18), rgba(1, 6, 12, 0.78));
}

.upgrade-forge-screen > * {
  position: relative;
  z-index: 1;
}

.upgrade-forge-screen .forge-map1-topbar {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) auto 44px;
  align-items: start;
  gap: 18px;
  margin-bottom: 18px;
}

.upgrade-forge-screen .forge-map1-title {
  display: flex;
  align-items: center;
  gap: 12px;
}

.upgrade-forge-screen .forge-map1-title img {
  width: 52px;
  height: 52px;
  padding: 8px;
  border: 1px solid rgba(50, 213, 255, 0.62);
  border-radius: 6px;
  background: rgba(6, 42, 64, 0.58);
  object-fit: contain;
}

.upgrade-forge-screen .forge-map1-title h2 {
  margin: 0;
  color: #dff8ff;
  font-size: clamp(2rem, 4vw, 3.4rem);
  line-height: 0.92;
  letter-spacing: 0;
  text-shadow: 0 0 18px rgba(48, 213, 255, 0.58);
}

.upgrade-forge-screen .forge-map1-title span,
.upgrade-forge-screen .forge-map1-tagline,
.upgrade-forge-screen .modern-store-panel-header span {
  color: #62e7ff;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0;
}

.upgrade-forge-screen .forge-map1-title span {
  display: block;
  margin-top: 6px;
  color: #bfefff;
  font-size: 1.05rem;
}

.upgrade-forge-screen .forge-map1-tagline {
  align-self: center;
  padding-top: 8px;
  color: #9eeaff;
  font-size: 0.88rem;
}

.upgrade-forge-screen .forge-map1-close {
  width: 44px;
  height: 44px;
  min-width: 44px;
  padding: 0;
  border-radius: 6px;
  font-size: 2rem;
  line-height: 1;
}

.upgrade-forge-screen .upgrade-forge-layout {
  display: grid;
  grid-template-columns: minmax(210px, 0.78fr) minmax(360px, 1.35fr) minmax(260px, 0.82fr);
  gap: 16px;
  min-height: min(640px, calc(100vh - 112px));
  align-items: stretch;
}

.upgrade-forge-screen .forge-panel {
  border: 1px solid rgba(51, 205, 255, 0.38);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(3, 17, 31, 0.9), rgba(1, 8, 16, 0.82));
  box-shadow: inset 0 0 28px rgba(37, 160, 220, 0.12), 0 0 26px rgba(0, 0, 0, 0.38);
}

.upgrade-forge-screen .forge-owned-panel,
.upgrade-forge-screen .forge-preview-panel {
  padding: 14px;
}

.upgrade-forge-screen .modern-store-panel-header {
  margin: 0 0 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(82, 199, 244, 0.24);
}

.upgrade-forge-screen .forge-selected-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: calc(100vh - 178px);
  overflow: auto;
  padding-right: 4px;
}

.upgrade-forge-screen .forge-owned-item {
  display: grid;
  grid-template-columns: 66px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 74px;
  padding: 9px 10px;
  border: 1px solid rgba(50, 169, 222, 0.24);
  border-radius: 6px;
  background: rgba(2, 14, 25, 0.72);
  color: #eef9ff;
  text-align: left;
}

.upgrade-forge-screen .forge-owned-item.selected {
  border-color: #31cfff;
  background: linear-gradient(90deg, rgba(0, 166, 255, 0.28), rgba(5, 27, 48, 0.78));
  box-shadow: inset 0 0 16px rgba(41, 202, 255, 0.28), 0 0 18px rgba(34, 197, 255, 0.28);
}

.upgrade-forge-screen .forge-owned-item img {
  width: 60px;
  height: 54px;
  object-fit: contain;
  filter: drop-shadow(0 0 8px rgba(54, 202, 255, 0.34));
}

.upgrade-forge-screen .forge-owned-item strong,
.upgrade-forge-screen .forge-owned-item small {
  display: block;
  letter-spacing: 0;
}

.upgrade-forge-screen .forge-owned-item strong {
  font-size: 0.98rem;
  color: #f4fbff;
}

.upgrade-forge-screen .forge-owned-item small {
  margin-top: 3px;
  color: #a8c6d7;
}

.upgrade-forge-screen .forge-chamber-panel {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border-color: transparent;
  background: transparent;
  box-shadow: none;
  overflow: visible;
}

.upgrade-forge-screen .forge-chamber-visual,
.upgrade-forge-screen .forge-chamber-visual.missing-materials {
  position: absolute;
  inset: 0;
  min-height: 100%;
  border: 0;
  background: transparent;
  box-shadow: none;
