.upgrade-forge-screen .forge-ring,
.upgrade-forge-screen .forge-beam,
.upgrade-forge-screen .forge-scanline,
.upgrade-forge-screen .forge-particles {
  display: block;
}

.upgrade-forge-screen .forge-chamber-item,
.upgrade-forge-screen #forgeChamber.forge-chamber-visual .forge-chamber-item {
  position: relative;
  z-index: 3;
  width: min(58%, 430px);
