.upgrade-forge-screen .forge-map1-shards img {
  grid-row: 1 / 3;
  width: 38px;
  height: 38px;
  object-fit: contain;
}

.upgrade-forge-screen .forge-map1-shards span {
  color: #6eeaff;
  font-size: 0.76rem;
  font-weight: 900;
  text-transform: uppercase;
}

.upgrade-forge-screen .forge-map1-shards strong {
  color: #63e8ff;
  font-size: 1.8rem;
  line-height: 1;
