/* ===== Forge energy signature and tier spectacle ===== */
.forge-tier-common {
  --forge-energy-opacity: 0.2;
  --forge-energy-soft: 0.05;
  --forge-energy-mid: 0.12;
  --forge-energy-bright: 0.3;
  --forge-energy-beam-low: 0.28;
  --forge-energy-beam-high: 0.42;
  --forge-energy-blur: 14px;
  --forge-energy-speed: 6.8s;
}

.forge-tier-refined {
  --forge-energy-opacity: 0.38;
  --forge-energy-soft: 0.1;
  --forge-energy-mid: 0.24;
  --forge-energy-bright: 0.5;
  --forge-energy-beam-low: 0.4;
  --forge-energy-beam-high: 0.62;
  --forge-energy-blur: 19px;
  --forge-energy-speed: 5.2s;
}

.forge-tier-unique {
  --forge-energy-opacity: 0.56;
  --forge-energy-soft: 0.16;
  --forge-energy-mid: 0.36;
  --forge-energy-bright: 0.7;
  --forge-energy-beam-low: 0.54;
  --forge-energy-beam-high: 0.76;
  --forge-energy-blur: 25px;
  --forge-energy-speed: 4.1s;
}

.forge-tier-elite {
  --forge-energy-opacity: 0.74;
  --forge-energy-soft: 0.23;
  --forge-energy-mid: 0.5;
  --forge-energy-bright: 0.86;
  --forge-energy-beam-low: 0.68;
  --forge-energy-beam-high: 0.9;
  --forge-energy-blur: 32px;
  --forge-energy-speed: 3.2s;
}

.forge-tier-super {
  --forge-energy-opacity: 0.94;
  --forge-energy-soft: 0.32;
  --forge-energy-mid: 0.68;
  --forge-energy-bright: 1;
  --forge-energy-beam-low: 0.82;
  --forge-energy-beam-high: 1;
  --forge-energy-blur: 42px;
  --forge-energy-speed: 2.35s;
}

#upgradeForgeScreen.upgrade-forge-screen.active {
  background:
    radial-gradient(circle at 72% 32%, rgba(30, 170, 255, 0.1), transparent 27%),
    linear-gradient(180deg, rgba(1, 10, 22, 0.78), rgba(1, 7, 15, 0.97)),
    url("assets/ui/forge/forge-background.png") center / cover no-repeat,
    #010712 !important;
}

#upgradeForgeScreen .forge-preview-panel {
  position: relative;
  isolation: isolate;
}

#upgradeForgeScreen .forge-preview-panel::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 52px 0 0;
  pointer-events: none;
  background:
    linear-gradient(115deg, transparent 0 46%, rgba(66, 198, 255, 0.025) 46% 47%, transparent 47% 100%),
    repeating-linear-gradient(0deg, transparent 0 34px, rgba(78, 188, 237, 0.025) 35px);
  mask-image: linear-gradient(180deg, black, transparent 88%);
}

#upgradeForgeScreen #forgePreviewOutput {
  display: inline-flex;
  align-items: center;
  min-height: 23px;
  padding: 3px 9px;
  border: 1px solid rgba(91, 218, 255, 0.35);
  border-radius: 999px;
  background: rgba(40, 176, 226, 0.08);
  color: #b9eefe;
  font-size: 0.61rem;
  letter-spacing: 0.08em;
}

#upgradeForgeScreen .forge-owned-art {
  position: relative !important;
  isolation: isolate;
}

#upgradeForgeScreen .forge-owned-art::before,
#upgradeForgeScreen .forge-owned-art::after {
  content: "";
  position: absolute;
  z-index: -1;
  top: 34px;
  left: 50%;
  width: 84px;
  height: 38px;
  pointer-events: none;
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

#upgradeForgeScreen .forge-owned-art::before {
  border: 1px solid rgba(var(--forge-tier-rgb), var(--forge-energy-bright));
  box-shadow:
    0 0 var(--forge-energy-blur) rgba(var(--forge-tier-rgb), var(--forge-energy-opacity)),
    inset 0 0 18px rgba(var(--forge-tier-rgb), var(--forge-energy-mid));
}

#upgradeForgeScreen .forge-owned-art::after {
  width: 62px;
  height: 62px;
  background: radial-gradient(circle, rgba(var(--forge-tier-rgb), var(--forge-energy-soft)), transparent 67%);
  filter: blur(4px);
}

#upgradeForgeScreen .forge-owned-art img {
  position: relative;
  z-index: 2;
}

#upgradeForgeScreen .forge-tier-refined .forge-owned-art::before,
#upgradeForgeScreen .forge-tier-unique .forge-owned-art::before,
#upgradeForgeScreen .forge-tier-elite .forge-owned-art::before,
#upgradeForgeScreen .forge-tier-super .forge-owned-art::before {
  animation: forgeInventoryAura var(--forge-energy-speed) linear infinite;
}

#upgradeForgeScreen .forge-tier-unique .forge-owned-art img,
#upgradeForgeScreen .forge-tier-elite .forge-owned-art img,
#upgradeForgeScreen .forge-tier-super .forge-owned-art img {
  animation: forgeInventoryItemPulse var(--forge-energy-speed) ease-in-out infinite;
}

#upgradeForgeScreen .forge-owned-item.forge-tier-elite,
#upgradeForgeScreen .forge-owned-item.forge-tier-super {
  box-shadow:
    inset 0 0 24px rgba(var(--forge-tier-rgb), 0.08),
    0 0 16px rgba(var(--forge-tier-rgb), var(--forge-energy-soft)) !important;
}

#upgradeForgeScreen .forge-showcase.forge-tier-scope {
  position: relative;
  overflow: hidden;
  box-shadow:
    inset 0 0 38px rgba(var(--forge-tier-rgb), var(--forge-energy-soft)),
    0 0 18px rgba(var(--forge-tier-rgb), var(--forge-energy-soft)) !important;
}

#upgradeForgeScreen .forge-showcase.forge-tier-scope::after {
  content: "";
  position: absolute;
  z-index: 5;
  top: -70%;
  bottom: -70%;
  left: -32%;
  width: 18%;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(var(--forge-tier-rgb), 0.17), transparent);
  opacity: var(--forge-energy-mid);
  transform: rotate(16deg);
  animation: forgeShowcaseSweep calc(var(--forge-energy-speed) * 1.9) ease-in-out infinite;
}

#upgradeForgeScreen #forgeChamber .forge-energy-orbit {
  position: absolute;
  z-index: 2;
  top: 50%;
  left: 50%;
  width: 70%;
  height: 45%;
  pointer-events: none;
  border: 1px solid rgba(var(--forge-tier-rgb), var(--forge-energy-bright));
  border-right-color: transparent;
  border-left-color: transparent;
  border-radius: 50%;
  box-shadow:
    0 0 var(--forge-energy-blur) rgba(var(--forge-tier-rgb), var(--forge-energy-mid)),
    inset 0 0 15px rgba(var(--forge-tier-rgb), var(--forge-energy-soft));
  transform: translate(-50%, -50%) rotate(-8deg);
}

#upgradeForgeScreen #forgeChamber .forge-energy-orbit.orbit-a {
  animation: forgeEnergyOrbit var(--forge-energy-speed) linear infinite;
}

#upgradeForgeScreen #forgeChamber .forge-energy-orbit.orbit-b {
  width: 52%;
  height: 68%;
  opacity: 0.72;
  transform: translate(-50%, -50%) rotate(72deg);
  animation: forgeEnergyOrbitReverse calc(var(--forge-energy-speed) * 1.28) linear infinite;
}

#upgradeForgeScreen #forgeChamber .forge-beam {
  position: absolute;
  z-index: 1;
  top: 6%;
  bottom: 6%;
  left: 50%;
  display: block;
  width: 3px;
  pointer-events: none;
  background: linear-gradient(180deg, transparent, rgba(var(--forge-tier-rgb), 0.92) 25% 75%, transparent);
  box-shadow: 0 0 20px 5px rgba(var(--forge-tier-rgb), var(--forge-energy-mid));
  opacity: var(--forge-energy-beam-low);
  transform: translateX(-50%);
  animation: forgeBeamBreathe calc(var(--forge-energy-speed) * 0.7) ease-in-out infinite;
}

#upgradeForgeScreen #forgeChamber .forge-particles {
  position: absolute;
  z-index: 2;
  inset: 10% 12%;
  display: block;
  pointer-events: none;
  background:
    radial-gradient(circle at 14% 64%, rgba(var(--forge-tier-rgb), 0.86) 0 1px, transparent 2px),
    radial-gradient(circle at 28% 26%, rgba(var(--forge-tier-rgb), 0.74) 0 1.5px, transparent 2.5px),
    radial-gradient(circle at 73% 18%, rgba(var(--forge-tier-rgb), 0.9) 0 1px, transparent 2px),
    radial-gradient(circle at 82% 69%, rgba(var(--forge-tier-rgb), 0.78) 0 1.5px, transparent 2.5px),
    radial-gradient(circle at 62% 84%, rgba(var(--forge-tier-rgb), 0.68) 0 1px, transparent 2px);
  opacity: var(--forge-energy-opacity);
  filter: drop-shadow(0 0 5px rgba(var(--forge-tier-rgb), 0.84));
  animation: forgeEnergyParticles calc(var(--forge-energy-speed) * 1.35) ease-in-out infinite alternate;
}

#upgradeForgeScreen #forgeChamber.forge-tier-common .forge-energy-orbit,
#upgradeForgeScreen #forgeChamber.forge-tier-common .forge-beam,
#upgradeForgeScreen #forgeChamber.forge-tier-common .forge-particles {
