  content: "";
  position: absolute;
  top: -60%;
  bottom: -60%;
  left: -35%;
  width: 18%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.5), transparent);
  transform: rotate(17deg);
  animation: forgeButtonCharge 3.2s ease-in-out infinite;
}

#upgradeForgeScreen #forgeChamber.forge-complete .forge-energy-orbit {
  animation-duration: 0.72s !important;
  border-width: 2px;
}

#upgradeForgeScreen #forgeChamber.forge-complete .forge-beam {
  animation: forgeCompletionBeam 1.35s ease-out both;
}

#upgradeForgeScreen #forgeChamber.forge-complete .forge-particles {
  animation: forgeCompletionParticles 1.55s ease-out both;
}

#upgradeForgeScreen #forgeChamber.forge-complete .forge-chamber-item {
  animation: forgeCompletionItem 1.5s cubic-bezier(0.17, 0.78, 0.22, 1) both !important;
}

@keyframes forgeInventoryAura {
  0% {
    transform: translate(-50%, -50%) rotate(0deg) scale(0.94);
    opacity: 0.55;
  }
  50% {
    transform: translate(-50%, -50%) rotate(180deg) scale(1.08);
    opacity: 1;
  }
  100% {
    transform: translate(-50%, -50%) rotate(360deg) scale(0.94);
    opacity: 0.55;
  }
}

@keyframes forgeInventoryItemPulse {
  0%,
  100% {
    transform: translateY(0) scale(0.98);
  }
  50% {
    transform: translateY(-2px) scale(1.03);
  }
}

@keyframes forgeShowcaseSweep {
  0%,
  30% {
    left: -32%;
  }
  72%,
  100% {
    left: 128%;
  }
}

@keyframes forgeEnergyOrbit {
  from {
    transform: translate(-50%, -50%) rotate(-8deg);
  }
  to {
    transform: translate(-50%, -50%) rotate(352deg);
  }
}

@keyframes forgeEnergyOrbitReverse {
  from {
    transform: translate(-50%, -50%) rotate(72deg);
  }
  to {
    transform: translate(-50%, -50%) rotate(-288deg);
  }
}

@keyframes forgeBeamBreathe {
  0%,
  100% {
    opacity: var(--forge-energy-beam-low);
    transform: translateX(-50%) scaleX(0.7);
  }
  50% {
    opacity: var(--forge-energy-beam-high);
    transform: translateX(-50%) scaleX(1.35);
  }
}

@keyframes forgeEnergyParticles {
  from {
    opacity: var(--forge-energy-mid);
    transform: translateY(4px) scale(0.96);
  }
  to {
    opacity: var(--forge-energy-opacity);
    transform: translateY(-5px) scale(1.04);
  }
}

@keyframes forgeItemEnergyPulse {
  0%,
  100% {
    transform: translate(-50%, -50%) scale(0.98);
  }
  50% {
    transform: translate(-50%, -53%) scale(1.045);
  }
}

@keyframes forgeNextTierReady {
  0%,
  100% {
    box-shadow: inset 0 0 15px rgba(var(--forge-tier-rgb), 0.07);
  }
  50% {
    box-shadow:
      inset 0 0 24px rgba(var(--forge-tier-rgb), 0.18),
      0 0 14px rgba(var(--forge-tier-rgb), 0.2);
  }
}

@keyframes forgeButtonCharge {
  0%,
  26% {
    left: -35%;
  }
  72%,
  100% {
    left: 128%;
  }
}

@keyframes forgeCompletionBeam {
  0% {
    opacity: 0.3;
    transform: translateX(-50%) scaleX(0.7);
  }
  36% {
    opacity: 1;
    transform: translateX(-50%) scaleX(5.5);
    box-shadow: 0 0 54px 18px rgba(var(--forge-tier-rgb), 0.92);
  }
  100% {
    opacity: 0.42;
    transform: translateX(-50%) scaleX(1);
  }
}

@keyframes forgeCompletionParticles {
  0% {
    opacity: 0;
    transform: scale(0.42);
  }
  42% {
    opacity: 1;
    transform: scale(1.36);
    filter: drop-shadow(0 0 12px rgba(var(--forge-tier-rgb), 1));
  }
  100% {
    opacity: var(--forge-energy-opacity);
    transform: scale(1);
  }
}

@keyframes forgeCompletionItem {
  0% {
    opacity: 0.55;
    transform: translate(-50%, -50%) scale(0.82) rotate(-2deg);
  }
  42% {
    opacity: 1;
    transform: translate(-50%, -53%) scale(1.18) rotate(1deg);
    filter:
      brightness(1.45)
      drop-shadow(0 0 42px rgba(var(--forge-tier-rgb), 1))
      drop-shadow(0 14px 16px rgba(0, 0, 0, 0.72));
  }
  100% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  #upgradeForgeScreen *,
  #upgradeForgeScreen *::before,
  #upgradeForgeScreen *::after {
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }
}

